// renderer.js — логика рабочего пространства: панорама, зум, ПКМ-меню, ноды, провода.
// Всё на ванильном JS без библиотек. «Мир» (#world) двигаем/масштабируем через CSS transform,
// сетку рисуем на #viewport, провода — в SVG внутри #world (в тех же координатах, что и ноды).

const svgns = 'http://www.w3.org/2000/svg';
const viewport = document.getElementById('viewport');
const world = document.getElementById('world');
const ctxmenu = document.getElementById('ctxmenu');

// Автосейв правок полей: любое ИЗМЕНЕНИЕ поля внутри ноды (blur/выбор в дропдауне) → снимок графа.
// Единая страховка от «слетающих» значений у нод без своего слушателя change (Опции, Озвучка и др.).
// Грузим граф через `.value=` (без события change) → на загрузке НЕ срабатывает. В пресете
// persistCurrentGraph — no-op (сохранение по 💾), поэтому дефолт-пресет случайно не перезапишем.
world.addEventListener('change', (e) => {
  const n = e.target && e.target.closest && e.target.closest('.node');
  if (n && typeof persistCurrentGraph === 'function') { try { persistCurrentGraph(); } catch (_) {} }
});

// SVG-слой для проводов, первым ребёнком мира — рисуется ПОД нодами.
// viewBox 1:1 и большой бокс (см. CSS) — чтобы события мыши на проводах ловились по всему холсту,
// а координаты пути совпадали с мировыми (точка «M 200 200» = мировые 200,200).
const wires = document.createElementNS(svgns, 'svg');
wires.id = 'wires';
wires.setAttribute('viewBox', '-50000 -50000 100000 100000');
world.appendChild(wires);

// Состояние камеры: смещение (x,y) в экранных px и масштаб.
const cam = { x: 0, y: 0, scale: 1 };
const MIN_SCALE = 0.2, MAX_SCALE = 3;
const GRID = 40;   // шаг сетки (world-px); линии/пересечения кратны GRID, снап по Shift магнитит к ним
let zTop = 10;

const connections = []; // { from, to, path, hit, waypoints:[{x,y}], wpEls:[] }
let wireStyle = 'elbow'; // 'curve' — волнистые (безье), 'elbow' — уголками (ортогональ). По умолчанию уголки. Переключается кнопкой внизу слева.
let draggingWp = null;   // сейчас тащим узловую точку провода (waypoint)
let wireGhost = null;    // «призрак» точки под курсором при наведении на провод

function render() {
  world.style.transform = `translate(${cam.x}px, ${cam.y}px) scale(${cam.scale})`;
  viewport.style.backgroundSize = `${GRID * cam.scale}px ${GRID * cam.scale}px`;
  viewport.style.backgroundPosition = `${cam.x}px ${cam.y}px`;
}
// Во время жестов рендер БАТЧИМ через requestAnimationFrame: pointermove сыпется чаще кадра,
// поэтому копим изменения и рисуем ОДИН раз за кадр — плавно, без «двойных» перерисовок и мерцания.
let renderScheduled = false;
function scheduleRender() {
  if (renderScheduled) return;
  renderScheduled = true;
  requestAnimationFrame(() => { renderScheduled = false; render(); });
}

function screenToWorld(clientX, clientY) {
  const r = viewport.getBoundingClientRect();
  return {
    x: (clientX - r.left - cam.x) / cam.scale,
    y: (clientY - r.top - cam.y) / cam.scale,
  };
}
const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
const raise = (el) => { el.style.zIndex = ++zTop; };

// ---- Выделение нескольких нод ----
// Shift+клик по ноде — добавить/убрать её из выделения; Shift+тащить по пустому месту — рамка.
// Тащишь выделенную ноду — двигается всё выделение; тащишь невыделенную — выделение сбрасывается.
const selection = new Set();
function selectNode(el) { if (el) { selection.add(el); el.classList.add('selected'); } }
function deselectNode(el) { if (el) { selection.delete(el); el.classList.remove('selected'); } }
function toggleSelect(el) { selection.has(el) ? deselectNode(el) : selectNode(el); }
function clearSelection() { selection.forEach((n) => n.classList.remove('selected')); selection.clear(); }

// РАНЬШЕ тут на время движения включался will-change:transform (GPU-слой). Отказались: #world тащит
// огромный SVG проводов (100000px), а слой такого размера НЕ влезает в текстуру GPU — на телефоне это
// давало мерцание и БЕЛЫЕ вспышки при пане/зуме. Без промоушена мир перерисовывается на месте (нод
// немного — дёшево), резко и без вспышек; плавность обеспечивает rAF-батчинг (scheduleRender).
function markCanvasBusy() { /* no-op: намеренно без will-change — см. комментарий выше */ }

// ---- Зум колесом к позиции курсора ----
viewport.addEventListener('wheel', (e) => {
  // Экран закреплён (кнопка 📌 в шапке ноды): холст заперт — колесо его НЕ зумит. Внутри закреплённой
  // ноды колесо крутит её содержимое (ленту, панели, открытый в ноде вижн) — браузер прокручивает сам,
  // раз мы не гасим событие; вне ноды колесо просто ничего не делает.
  if (screenPinned) { if (!(e.target && e.target.closest && e.target.closest('.node.scr-pinned'))) e.preventDefault(); return; }
  e.preventDefault();
  const r = viewport.getBoundingClientRect();
  const mx = e.clientX - r.left, my = e.clientY - r.top;
  const factor = Math.exp(-e.deltaY * 0.0015);
  const newScale = clamp(cam.scale * factor, MIN_SCALE, MAX_SCALE);
  cam.x = mx - (mx - cam.x) * (newScale / cam.scale);
  cam.y = my - (my - cam.y) * (newScale / cam.scale);
  cam.scale = newScale;
  scheduleRender();
}, { passive: false });

// ---- Навигация по холсту: пан (один палец/ЛКМ) + pinch «зум+пан» (два пальца) + рамка (Shift/Ctrl, мышь) ----
// move/up слушаем на WINDOW и БЕЗ setPointerCapture — так надёжнее для мультитача: второй палец не
// теряется, события приходят даже если палец ушёл за край холста (capture на первом пальце «крал» их).
let panning = null, selbox = null;
const activePtrs = new Map();   // pointerId -> {x,y}: активные касания/указатели
let pinch = null;               // {d, scale, wx, wy}: расстояние и МИРОВАЯ точка-якорь на старте щипка
let winPtrOn = false;
const ptrList = () => [...activePtrs.values()];
function startPinch() {
  const [a, b] = ptrList();
  const r = viewport.getBoundingClientRect();
  const d = Math.hypot(a.x - b.x, a.y - b.y) || 1;
  const mx = (a.x + b.x) / 2 - r.left, my = (a.y + b.y) / 2 - r.top;
  // мировую точку под серединой щипка держим под серединой всё время → зум и пан двумя пальцами вместе
  pinch = { d, scale: cam.scale, wx: (mx - cam.x) / cam.scale, wy: (my - cam.y) / cam.scale };
}
function winPtrMove(e) {
  if (!activePtrs.has(e.pointerId)) return;
  activePtrs.set(e.pointerId, { x: e.clientX, y: e.clientY });
  if (pinch && activePtrs.size >= 2) {                 // два пальца: масштаб по расстоянию + пан по середине
    const [a, b] = ptrList();
    const r = viewport.getBoundingClientRect();
    const nd = Math.hypot(a.x - b.x, a.y - b.y);
    const mx = (a.x + b.x) / 2 - r.left, my = (a.y + b.y) / 2 - r.top;
    const newScale = clamp(pinch.scale * (nd / pinch.d), MIN_SCALE, MAX_SCALE);
    cam.scale = newScale;
    cam.x = mx - pinch.wx * newScale;                  // якорную мировую точку — под текущую середину
    cam.y = my - pinch.wy * newScale;
    scheduleRender();
    return;
  }
  if (selbox) { selbox.cx = e.clientX; selbox.cy = e.clientY; layoutSelBox(); return; }
  if (!panning) return;
  panning.moved = panning.moved || Math.hypot(e.clientX - panning.sx, e.clientY - panning.sy) > 3;
  cam.x = panning.ox + (e.clientX - panning.sx);
  cam.y = panning.oy + (e.clientY - panning.sy);
  scheduleRender();
}
function winPtrUp(e) {
  if (!activePtrs.has(e.pointerId)) return;
  activePtrs.delete(e.pointerId);
  if (activePtrs.size < 2) pinch = null;
  if (selbox) { commitSelBox(); selbox.box.remove(); selbox = null; }
  else if (panning && !panning.moved && activePtrs.size === 0) clearSelection();   // чистый клик/тап — снять выделение
  if (activePtrs.size === 0) {
    panning = null; viewport.classList.remove('panning');
    document.body.classList.remove('canvas-dragging');          // вернуть выделение текста
    window.removeEventListener('pointermove', winPtrMove);
    window.removeEventListener('pointerup', winPtrUp);
    window.removeEventListener('pointercancel', winPtrUp);
    winPtrOn = false;
  } else if (activePtrs.size === 1 && !pinch) {         // после щипка остался один палец → продолжаем пан им
    const p = ptrList()[0];
    panning = { sx: p.x, sy: p.y, ox: cam.x, oy: cam.y, moved: true };
    viewport.classList.add('panning');
  }
}
// ЗАЛИПЫ. Если указатель "потерялся" (свернули окно, alt-tab, вход/выход из полноэкранного, система
// перехватил жест) — pointerup не приходит, и холст навсегда остаётся в состоянии перетаскивания:
// висит рамка выделения, не работают клики и ПКМ-меню, выпадашки нод не открываются. Сбрасываем
// всё при потере фокуса и при уходе вкладки в фон — состояние жеста живёт только пока окно активно.
function resetPointerState() {
  try {
    activePtrs.clear(); pinch = null; panning = null;
    viewport.classList.remove('panning');
    document.body.classList.remove('canvas-dragging');
    if (selbox) { try { selbox.box.remove(); } catch (_) {} selbox = null; }
    if (winPtrOn) {
      window.removeEventListener('pointermove', winPtrMove);
      window.removeEventListener('pointerup', winPtrUp);
      window.removeEventListener('pointercancel', winPtrUp);
      winPtrOn = false;
    }
    if (draggingWp) draggingWp = null;
    const cm = document.getElementById('ctxmenu'); if (cm) cm.classList.remove('show');   // и зависшее ПКМ-меню
  } catch (_) {}
}
window.addEventListener('blur', resetPointerState);
document.addEventListener('visibilitychange', () => { if (document.hidden) resetPointerState(); });

viewport.addEventListener('pointerdown', (e) => {
  if (e.pointerType === 'mouse' && e.button !== 0) return;   // мышь — только ЛКМ (ПКМ = меню)
  if (e.target.closest('.node')) return;
  if (screenPinned) return;                                  // экран закреплён на ноде — холст не панорамируем и рамку не тянем
  document.body.classList.add('canvas-dragging');            // гасим выделение текста на время работы с холстом (пан/рамка/пинч)
  const _sel = window.getSelection && window.getSelection(); if (_sel && !_sel.isCollapsed) _sel.removeAllRanges();   // сбросить уже начатое выделение
  activePtrs.set(e.pointerId, { x: e.clientX, y: e.clientY });
  if (!winPtrOn) {                                      // move/up — на window (не теряем события и второй палец)
    winPtrOn = true;
    window.addEventListener('pointermove', winPtrMove, { passive: false });
    window.addEventListener('pointerup', winPtrUp);
    window.addEventListener('pointercancel', winPtrUp);
  }
  if (activePtrs.size === 2) {                          // второй палец → pinch (зум+пан), отменяем одиночный пан/рамку
    panning = null; viewport.classList.remove('panning');
    if (selbox) { selbox.box.remove(); selbox = null; }
    startPinch();
    return;
  }
  if (activePtrs.size > 2) return;
  hideMenu(); closeDropdowns();
  if (e.pointerType === 'mouse' && (e.shiftKey || e.ctrlKey || e.metaKey)) {   // рамка выделения — только мышь
    const r = viewport.getBoundingClientRect();
    const box = document.createElement('div'); box.id = 'selbox';
    viewport.appendChild(box);
    selbox = { sx: e.clientX, sy: e.clientY, cx: e.clientX, cy: e.clientY, r, box };
    layoutSelBox();
    return;
  }
  panning = { sx: e.clientX, sy: e.clientY, ox: cam.x, oy: cam.y, moved: false };
  viewport.classList.add('panning');
});

// Прямоугольник рамки в экранных px (относительно #viewport).
function layoutSelBox() {
  const { sx, sy, cx, cy, r, box } = selbox;
  box.style.left = (Math.min(sx, cx) - r.left) + 'px';
  box.style.top = (Math.min(sy, cy) - r.top) + 'px';
  box.style.width = Math.abs(cx - sx) + 'px';
  box.style.height = Math.abs(cy - sy) + 'px';
}
// Кого рамка накрыла — добавить в выделение (рамка ДОБАВЛЯЕТ к текущему, не сбрасывая).
function commitSelBox() {
  const a = screenToWorld(selbox.sx, selbox.sy), b = screenToWorld(selbox.cx, selbox.cy);
  const x1 = Math.min(a.x, b.x), y1 = Math.min(a.y, b.y);
  const x2 = Math.max(a.x, b.x), y2 = Math.max(a.y, b.y);
  world.querySelectorAll(':scope > .node').forEach((n) => {
    const nx = parseFloat(n.style.left), ny = parseFloat(n.style.top);
    if (nx < x2 && nx + n.offsetWidth > x1 && ny < y2 && ny + n.offsetHeight > y1) selectNode(n);
  });
}

// ---- Контекстное меню (ПКМ по пустому месту) ----
let menuWorldPos = { x: 0, y: 0 };
viewport.addEventListener('contextmenu', (e) => {
  if (e.target.closest('.node')) { e.preventDefault(); return; }
  e.preventDefault();
  menuWorldPos = screenToWorld(e.clientX, e.clientY);
  ctxmenu.style.left = e.clientX + 'px';
  ctxmenu.style.top = e.clientY + 'px';
  ctxmenu.classList.remove('hidden');
});
function hideMenu() { ctxmenu.classList.add('hidden'); }
function closeDropdowns() { document.querySelectorAll('.dd-list').forEach((l) => l.classList.add('hidden')); }
window.addEventListener('click', () => { hideMenu(); closeDropdowns(); });
ctxmenu.addEventListener('click', (e) => {
  const a = e.target.dataset.action;
  if (a === 'new-api') createNode('api', menuWorldPos.x, menuWorldPos.y);
  else if (a === 'new-options') createNode('options', menuWorldPos.x, menuWorldPos.y);
  else if (a === 'new-local') createNode('local', menuWorldPos.x, menuWorldPos.y);
  else if (a === 'new-sys') createNode('sysprompt', menuWorldPos.x, menuWorldPos.y);
  else if (a === 'new-prompt') {
    if (document.querySelector('.node-prompt')) alertOnce('«Промт комплитер» может быть только один — он уже есть в сборке. Открой его вижном из 🔧 в чате.');
    else createNode('prompt', menuWorldPos.x, menuWorldPos.y);
  }
  else if (a === 'new-mprompt') createNode('mprompt', menuWorldPos.x, menuWorldPos.y);
  else if (a === 'new-char') createNode('character', menuWorldPos.x, menuWorldPos.y);
  else if (a === 'new-persona') createNode('persona', menuWorldPos.x, menuWorldPos.y);
  else if (a === 'new-lore') createNode('lorebook', menuWorldPos.x, menuWorldPos.y);
  else if (a === 'new-chat') createNode('chat', menuWorldPos.x, menuWorldPos.y);
  else if (a === 'new-groupchat') createNode('groupchat', menuWorldPos.x, menuWorldPos.y);
  else if (a === 'new-netgame') createNode('netgame', menuWorldPos.x, menuWorldPos.y);
  else if (a === 'new-scanner') createNode('scanner', menuWorldPos.x, menuWorldPos.y);
  else if (a === 'new-soul') createNode('soul', menuWorldPos.x, menuWorldPos.y);
  else if (a === 'new-chronicle') createNode('chronicle', menuWorldPos.x, menuWorldPos.y);
  else if (a === 'new-critic') createNode('critic', menuWorldPos.x, menuWorldPos.y);
  else if (a === 'new-director') createNode('director', menuWorldPos.x, menuWorldPos.y);
  else if (a === 'new-embedder') createNode('embedder', menuWorldPos.x, menuWorldPos.y);
  else if (a === 'new-translator') createNode('translator', menuWorldPos.x, menuWorldPos.y);
  else if (a === 'new-tts') createNode('tts', menuWorldPos.x, menuWorldPos.y);
  else if (a === 'new-state') createNode('state', menuWorldPos.x, menuWorldPos.y);
  else if (a === 'new-objective') createNode('objective', menuWorldPos.x, menuWorldPos.y);
  else if (a === 'new-note') createNode('note', menuWorldPos.x, menuWorldPos.y);
  else if (a === 'new-random') createNode('random', menuWorldPos.x, menuWorldPos.y);
  else if (a === 'new-dry') createNode('dry', menuWorldPos.x, menuWorldPos.y);
  hideMenu();
});

