// ---- Создание нод ----
function createNode(type, wx, wy) {
  let el;
  if (type === 'api') el = buildApiNode();
  else if (type === 'options') el = buildOptionsNode();
  else if (type === 'local') el = buildLocalNode();
  else if (type === 'sysprompt') el = buildSysPromptNode();
  else if (type === 'prompt') el = buildPromptNode();
  else if (type === 'mprompt') el = buildMpromptNode();
  else if (type === 'narrator') el = buildNarratorNode();
  else if (type === 'character') el = buildCharacterNode();
  else if (type === 'persona') el = buildPersonaNode();
  else if (type === 'lorebook') el = buildLorebookNode();
  else if (type === 'chat') el = buildChatNode();
  else if (type === 'groupchat') el = buildGroupChatNode();
  else if (type === 'scanner') el = buildScannerNode();
  else if (type === 'soul') el = buildSoulNode();
  else if (type === 'chronicle') el = buildChronicleNode();
  else if (type === 'critic') el = buildCriticNode();
  else if (type === 'director') el = buildDirectorNode();
  else if (type === 'embedder') el = buildEmbedderNode();
  else if (type === 'translator') el = buildTranslatorNode();
  else if (type === 'tts') el = buildTtsNode();
  else if (type === 'telegram') el = buildNetgameNode();   // отдельной ноды Telegram больше нет — старые сборки открываем как «Сетевую игру»
  else if (type === 'netgame') el = buildNetgameNode();
  else if (type === 'state') el = buildStateNode();
  else if (type === 'objective') el = buildObjectiveNode();
  else if (type === 'note') el = buildNoteNode();
  else if (type === 'random') el = buildRandomNode();
  else if (type === 'dry') el = buildDryNode();
  else return;
  el.style.left = wx + 'px';
  el.style.top = wy + 'px';
  world.appendChild(el);
  makeDraggable(el, el.querySelector('.node-head'));
  el.addEventListener('pointerdown', () => raise(el));
  el.querySelectorAll('.field, .dropdown, .chat-frame').forEach((f) =>
    f.addEventListener('pointerdown', (e) => e.stopPropagation()));
  el.querySelectorAll('.port').forEach((p) => { // входы плашек уже привязаны — не дублируем
    if (p.dataset.bound) return;
    p.dataset.bound = '1';
    p.addEventListener('pointerdown', onPortDown);
  });
  const closeBtn = el.querySelector('.node-close');
  closeBtn.addEventListener('pointerdown', (e) => e.stopPropagation()); // крестик не тащит/не сворачивает
  closeBtn.addEventListener('click', (e) => { e.stopPropagation(); removeNode(el); });
  instrumentTranslateFields(el);   // кнопки перевода на текстовых полях (RU-предпросмотр / EN-замена)
  raise(el);
  return el;
}

const corners = () =>
  `<span class="corner tl"></span><span class="corner tr"></span>
   <span class="corner bl"></span><span class="corner br"></span>`;
// Розетки: вход слева, выход справа.
const ports = () =>
  `<span class="port in" data-dir="in"></span><span class="port out" data-dir="out"></span>`;
// Шапка ноды: иконка, подпись, «галка сворачивания» и крестик удаления.
const head = (icon, label) =>
  `<div class="node-head"><div class="icon">${icon}</div><div class="label">${label}</div>
     <span class="node-caret">▾</span><button class="node-close" title="Удалить ноду">✕</button></div>`;

// «📌 Закрепить экран» — как вижн, только БЕЗ вижна: камера наводится на ноду (она занимает экран целиком),
// а холст запирается — не улетает от колеса, не таскается мышью/пальцем, ноду не сдвинуть случайно.
// Колесо внутри ноды при этом крутит её содержимое (лента, панели, открытый в ноде вижн). Отжали —
// камера возвращается ровно туда, где была. Закреплена всегда только ОДНА нода.
let screenPinned = null;   // { el, cam } — что закреплено и куда вернуть камеру
function pinScreenOn(el) {
  if (screenPinned) pinScreenOff();
  const r = el.getBoundingClientRect(), vr = viewport.getBoundingClientRect();
  const vw = vr.width || window.innerWidth, vh = vr.height || window.innerHeight;
  if (!vw || !vh || !r.width) { el.classList.add('scr-pinned'); document.body.classList.add('screen-pinned'); screenPinned = { el, cam: { ...cam } }; pinBtnsSync(); return; }   // окно свёрнуто/не отрисовано — просто запираем холст, камеру не трогаем
  const w = r.width / cam.scale, h = r.height / cam.scale;                 // размеры ноды в МИРОВЫХ px
  const wx = (r.left - vr.left - cam.x) / cam.scale, wy = (r.top - vr.top - cam.y) / cam.scale;
  const pad = 24;
  const scale = clamp(Math.min((vw - pad * 2) / w, (vh - pad * 2) / h), MIN_SCALE, MAX_SCALE);
  screenPinned = { el, cam: { ...cam } };                                  // куда вернуться при отжатии
  cam.scale = scale;
  cam.x = (vw - w * scale) / 2 - wx * scale;                               // нода по центру экрана
  cam.y = (vh - h * scale) / 2 - wy * scale;
  render();
  el.classList.add('scr-pinned');
  document.body.classList.add('screen-pinned');
  pinBtnsSync();
}
function pinScreenOff() {
  if (!screenPinned) return;
  const { el, cam: bak } = screenPinned;
  screenPinned = null;
  el.classList.remove('scr-pinned');
  document.body.classList.remove('screen-pinned');
  Object.assign(cam, bak); render();                                       // холст — как до закрепления
  pinBtnsSync();
}
function pinBtnsSync() {
  document.querySelectorAll('.node-pin').forEach((b) => {
    const node = b.closest('.node'); const on = !!(node && node.classList.contains('scr-pinned'));
    b.classList.toggle('on', on);
    b.title = on ? 'Экран закреплён: холст заперт, колесо крутит содержимое ноды. Нажми, чтобы вернуть холст как было'
                 : 'Закрепить экран: навести на эту ноду и запереть холст (не улетает от колеса, не таскается)';
  });
}
function nodePinScreenBtn(el) {
  const headEl = el.querySelector('.node-head'); if (!headEl || headEl.querySelector('.node-pin')) return;
  const b = document.createElement('button');
  b.className = 'node-eye node-pin'; b.type = 'button'; b.textContent = '📌';
  headEl.insertBefore(b, headEl.querySelector('.node-caret'));
  b.addEventListener('pointerdown', (e) => e.stopPropagation());
  b.addEventListener('click', (e) => { e.stopPropagation(); if (el.classList.contains('scr-pinned')) pinScreenOff(); else pinScreenOn(el); });
  pinBtnsSync();
}

// Кастомный выпадающий список, где под КАЖДОЙ опцией — описание «что делает» (нативный <select>
// так не умеет). options: [{value, label, desc}]. Ведёт себя КАК <select>: у элемента есть
// свойство `value` (чтение/запись), а при выборе пользователем стреляет событие `change` —
// поэтому старый код (`.value`, `addEventListener('change')`) работает без переделок.
function describedDropdown(options, value, onChange) {
  const dd = document.createElement('div');
  dd.className = 'dropdown dd-desc';
  const cur = document.createElement('div'); cur.className = 'dd-current';
  const list = document.createElement('div'); list.className = 'dd-list hidden';
  dd.append(cur, list);
  const labelOf = (v) => { const o = options.find((x) => x.value === v); return o ? o.label : (v || ''); };
  let _value = value;
  options.forEach((o) => {
    const opt = document.createElement('div');
    opt.className = 'dd-opt';
    opt.dataset.value = o.value;
    opt.innerHTML = `<div class="dd-opt-name"></div><div class="dd-opt-desc"></div>`;
    opt.querySelector('.dd-opt-name').textContent = o.label;
    opt.querySelector('.dd-opt-desc').textContent = o.desc || '';
    list.appendChild(opt);
  });
  const render = () => {
    cur.textContent = labelOf(_value);
    list.querySelectorAll('.dd-opt').forEach((o) => o.classList.toggle('sel', o.dataset.value === _value));
  };
  Object.defineProperty(dd, 'value', { configurable: true, get() { return _value; }, set(v) { _value = v; render(); } });
  render();
  dd.addEventListener('pointerdown', (e) => e.stopPropagation());   // клик по меню не тащит ноду
  cur.addEventListener('click', (e) => {
    e.stopPropagation();
    const wasHidden = list.classList.contains('hidden');
    closeDropdowns();
    if (wasHidden) list.classList.remove('hidden');
  });
  list.addEventListener('click', (e) => {
    const opt = e.target.closest('.dd-opt'); if (!opt) return;
    _value = opt.dataset.value; render();
    list.classList.add('hidden');
    dd.dispatchEvent(new Event('change', { bubbles: true }));   // как нативный select
    if (onChange) onChange(_value);
  });
  return dd;
}
// Заменить нативный <select class="cls"> внутри root на дропдаун с описанием (тот же класс,
// то же .value/событие change) — чтобы у КАЖДОЙ ноды в меню под опцией было видно, что она делает.
function selectToDropdown(root, cls, options) {
  const sel = root.querySelector('select.' + cls); if (!sel) return null;
  const dd = describedDropdown(options, sel.value);
  dd.classList.add(cls);
  sel.replaceWith(dd);
  return dd;
}
