  st.rows.forEach((r) => {
    const esc = (window.CSS && CSS.escape) ? CSS.escape(r.id) : r.id;
    const it = compEl.querySelector('.pm-item[data-id="' + esc + '"]'); if (!it) return;
    let b = it.querySelector('.pm-tok');
    if (!b) { b = document.createElement('span'); b.className = 'pm-tok'; const row = it.querySelector('.pm-row'); const caret = row && row.querySelector('.pm-caret'); if (row) row.insertBefore(b, caret || null); }
    b.textContent = r.on ? ('≈' + fmtTok(r.tok)) : '—';
    b.title = r.on ? ('Приблизительно ' + r.tok + ' токенов в этой плашке (точный счёт знает только провайдер)') : 'Плашка выключена — в промт не идёт';
    b.classList.toggle('zero', r.on && !r.tok);
  });
