    let t = head.querySelector('.pm-tok-total');
    if (!t) { t = document.createElement('span'); t.className = 'pm-tok-total'; head.insertBefore(t, head.querySelector('.node-eye') || head.querySelector('.node-caret')); }
    const lim = contextLimitFor(compEl);
