  set('.lb-keys', e.keys); set('.lb-keys2', e.keys2); set('.lb-logic', e.logic);
  set('.lb-whole', e.whole); set('.lb-case', e.case); set('.lb-content', e.content);
  set('.lb-ignorebudget', e.ignoreBudget);   // пин «всегда в промт (мимо бюджета)»
  set('.lb-prob', e.prob);
  set('.lb-sticky', e.sticky); set('.lb-cooldown', e.cooldown); set('.lb-delay', e.delay); // тайминги (только Режиссёр)
