    const vt = g('.lb-vecthr'); if (vt) e.vecThreshold = vt.value;
    const pr = g('.lb-prob'); if (pr) e.prob = pr.value;                 // «Вероятность» только у Режиссёра
    e.dependsOn = g('.lb-depends').value; e.chainDelay = g('.lb-chaindelay').value;
