    view._sel = master._sel || (master._entries[0] && master._entries[0].id);
    if (isDir) { view._gen = master._gen || (master._gen = directorGenDefaults()); view._master = master; view._chatNode = document.querySelector('.node-chat') || document.querySelector('.node-netgame') || document.querySelector('.node-telegram'); if (typeof renderDirectorGen === 'function') renderDirectorGen(view); }
    const sc = master.querySelector('.lb-scope-dd'), vsc = view.querySelector('.lb-scope-dd'); if (sc && vsc) vsc.value = sc.value;
