    const act = await chroniclePreview(node, { ptitle: '🎭 Персонаж · превью', pcount: curName, lblTitle: 'Имя (ключ поиска)', lblContent: 'Карточка персонажа', title: curName, content: card, keywords: [curName],
      genPrompt: curBrief, genLabel: 'Запрос — что за персонаж', genTranslate: true, genOpen: true, noKeys: true });   // окно простое: имя + карточка + запрос; ключ = имя (ставится сам)
