  const SKIP = ['Систем-промт', 'Основной промт', 'Инструкции после истории', 'История чата', 'Префилл', 'Редактура'];
  const seen = new Set();
  return msgs.filter((m) => m && m._src && !SKIP.includes(m._src) && String(m.content || '').trim())
    .filter((m) => { const k = m._src + '|' + m.content; if (seen.has(k)) return false; seen.add(k); return true; })
    .map((m) => '### ' + m._src + '\n' + String(m.content).trim())
    .join('\n\n').slice(0, 12000);
