    const label = Object.keys(byTier).sort().map((t) => byTier[t] + '×' + chrTier(t).label.toLowerCase()).join(', ');
    note('🗂 Свёрнуто: ' + label + '.');
    if (chatNode) chatToast(chatNode, '🗂 консолидация: ' + label, 'ok');
