  if (!container) { openLoreFs(master); return; }              // нет контейнера чата — фолбэк на обычный вижн
  closeChatVision();                                           // один вид за раз
  const toc = container.querySelector(':scope > .chr-toc.show'); if (toc) toc.classList.remove('show');
  const isDir = master.classList.contains('node-director');    // Режиссёр — тот же движок записей, но свои триггеры/тайминги во сборке DOM
  const view = isDir ? buildDirectorNode() : buildLorebookNode();   // тот же билдер — не дублируем UI-код
  view.classList.remove('node-lore', 'node-director');        // не графовая нода (мимо .node-lore/.node-director запросов)
  view.classList.add('lore-fs-node', 'lore-view');            // полный вид (шапка/порты скрыты)
  view._entries = master._entries;                            // ОБЩИЕ данные (не копия!)
  view._sel = selId || master._sel || (master._entries[0] && master._entries[0].id);
  if (isDir) { view._gen = master._gen || (master._gen = directorGenDefaults()); view._master = master; view._chatNode = chatNode; renderDirectorGen(view); }   // опции — общий объект с мастером; ссылки на мастера/чат для ручной генерации из вижна
  const sc = master.querySelector('.lb-scope-dd'), vsc = view.querySelector('.lb-scope-dd'); if (sc && vsc) vsc.value = sc.value;
  loreRenderList(view); loreRenderEditor(view);
