        if (pr.phase === 'load') { if (lastPhase !== 'load') chatProc(chatEl, 'load', 'Подгрузка модели', { cancelable: true }); }
        else chatProc(chatEl, 'grow', 'Генерация аудио', { frac: pr.value || 0, cancelable: true });   // генерация аудио — прогресс по времени
