  if (!r || !r.ok) { chatToast(chatEl, 'озвучка: ' + ((r && r.error) || 'ошибка'), 'err'); chatProc(chatEl, 'idle'); setTtsStatus(tts, '⚠ ' + ((r && r.error) || 'ошибка')); return; }
  chatProc(chatEl, 'done', 'Готово');
