  // плеер (играть/пауза, перемотка, перегенерация) и сразу проигрывает.
  const audioKey = msg ? msg.text : null;   // привязка звука к ТЕКСТУ реплики: перегенерят/правят → ключ иной → старый плеер прячется (не висит чужой звук)
  const frames = chatFrames();
