  const source = ttsVoiceSource(tts);
  if (source.mode === 'clone' && !source.ref) { setTtsStatus(tts, '⚠ выбери образец голоса (WAV)'); return; }
  if (source.mode === 'design' && !source.instruct) { setTtsStatus(tts, '⚠ генератор: выбери хотя бы одну черту голоса'); return; }
  const text = ((tts.querySelector('.tts-test') || {}).value || '').replace(/\*+/g, '').replace(/[«»“”]/g, '"').trim();
  if (!text) { setTtsStatus(tts, '⚠ впиши фразу для пробы'); return; }
