  a.addEventListener('ended', () => { URL.revokeObjectURL(url); if (_ttsCurrentAudio === a) _ttsCurrentAudio = null; });
  if (_ttsCurrentAudio) { try { _ttsCurrentAudio.pause(); } catch (_) { /* игнор */ } }
  _ttsCurrentAudio = a; a.play().catch(() => {});
