  const tg = el.querySelector('.tts-tagging'); if (tg && s.tagging != null) tg.checked = !!s.tagging;
  if (s.nums) [...el.querySelectorAll('.tts-p')].forEach((i) => { if (s.nums[i.dataset.key] != null) i.value = s.nums[i.dataset.key]; });
  if (s.bools) [...el.querySelectorAll('.tts-b')].forEach((c) => { if (s.bools[c.dataset.key] != null) c.checked = !!s.bools[c.dataset.key]; });
