  const rt = el.querySelector('.tts-reftext'); if (rt) rt.value = it.refText || '';
  const si = el.querySelector('.tts-seed-input'); if (si) si.value = (it.seed != null ? it.seed : -1);   // seed голоса → в поле (−1 если не задан)
  el._lastSeed = null; ttsShowSeed(el, null);
