  const vs = el.querySelector('.tts-voices-sel'); if (vs) vs.value = id;
  el._activeVoiceId = id;   // этот профиль теперь активный — «💾» будет его ОБНОВЛЯТЬ
  el._voiceMode = 'clone'; ttsApplyMode(el);
