  const settings = ttsReadSettings(el);   // весь профиль настроек (язык, тегетирование, все параметры/галочки)
  const lib = ttsVoiceLib();
  // ОБНОВИТЬ активный профиль (если не «➕ новый»): по _activeVoiceId, иначе по выбору в выпадашке, иначе (клон) по файлу.
