let _alertTs = 0;
function alertOnce(m) { const t = performance.now(); if (t - _alertTs > 1500) { _alertTs = t; alert(m); } }

// ── Почтальон Telegram (Bot API через прямой fetch к api.telegram.org) ────────────
// Только ПК/Electron: CSP расширен на api.telegram.org. Токен виден в запросах — для личного
// бота приемлемо (решение в research). Long polling: getUpdates держит соединение до ~25с,
// поэтому цикл ждёт события, а не долбит сервер.
const TG_API = 'https://api.telegram.org/bot';
const RLM_BUILD = '2026-08-28-rich-3';   // метка сборки: видна в ноде — сразу понятно, свежий ли код в окне
const tgSleep = (ms) => new Promise((r) => setTimeout(r, ms));
async function tgCall(token, method, params) {
  try {
    const res = await fetch(TG_API + token + '/' + method, {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(params || {}),
    });
    return await res.json();                    // { ok, result } | { ok:false, description }
  } catch (e) {
    return { ok: false, description: String((e && e.message) || e) };
  }
}
const tgSendMessage = (token, chatId, text, threadId, parseMode, extra) => tgCall(token, 'sendMessage', Object.assign({ chat_id: chatId, text }, threadId != null ? { message_thread_id: threadId } : {}, parseMode ? { parse_mode: parseMode } : {}, extra || {}));
const tgEditMessage = (token, chatId, messageId, text, parseMode, extra) => tgCall(token, 'editMessageText', Object.assign({ chat_id: chatId, message_id: messageId, text }, parseMode ? { parse_mode: parseMode } : {}, extra || {}));   // ручной фидбек критика: переписать прошлый ответ бота на месте
// ── Красивая разметка: Rich Messages (Bot API 10.1, июнь 2026) ────────────────────
// sendRichMessage принимает ОБЫЧНЫЙ markdown строкой (**жирный**, # заголовки, списки, > цитаты,
// таблицы, ||спойлер||, <details>) — без капризного экранирования MarkdownV2 и с потолком 32768
// символов вместо 4096. Разметку пишем ВСЕГДА в этом диалекте, а вниз по лестнице конвертируем.
const tgSendRich = (token, chatId, markdown, threadId, extra) => tgCall(token, 'sendRichMessage', Object.assign({ chat_id: chatId, rich_message: { markdown } }, threadId != null ? { message_thread_id: threadId } : {}, extra || {}));
const tgEditRich = (token, chatId, messageId, markdown, extra) => tgCall(token, 'editMessageText', Object.assign({ chat_id: chatId, message_id: messageId, rich_message: { markdown } }, extra || {}));
// Rich-сообщение С МЕДИА ВНУТРИ: картинка, голосовое и музыка живут в ОДНОМ сообщении вместе с текстом.
// В разметке на них ссылаются как ![](tg://photo?id=X) / ![](tg://audio?id=X), а сами файлы едут
// в поле media (InputRichMessageMedia + attach://). Поэтому запрос — multipart, а не JSON.
// items: [{ id, type: 'photo'|'audio'|'voice_note', b64, mime, name }]
async function tgSendRichMedia(token, chatId, markdown, items, threadId, extra) {
  try {
    const fd = new FormData();
    fd.append('chat_id', String(chatId));
    if (threadId != null) fd.append('message_thread_id', String(threadId));
    const media = [];
    (items || []).forEach((m, i) => {
      const att = 'f' + i;
      media.push({ id: m.id, media: { type: m.type, media: 'attach://' + att } });
      const bytes = Uint8Array.from(atob(m.b64), (c) => c.charCodeAt(0));
      fd.append(att, new Blob([bytes], { type: m.mime || 'application/octet-stream' }), m.name || att);
    });
    fd.append('rich_message', JSON.stringify(media.length ? { markdown, media } : { markdown }));
    Object.entries(extra || {}).forEach(([k, v]) => { if (v != null) fd.append(k, typeof v === 'string' ? v : JSON.stringify(v)); });
    const res = await fetch(TG_API + token + '/sendRichMessage', { method: 'POST', body: fd });
    const j = await res.json();
    tgRichLog('sendRichMessage+media', j && j.ok, (j && j.description) || '', { files: (items || []).length, len: (markdown || '').length });
    return j;
  } catch (e) { return { ok: false, description: String((e && e.message) || e) }; }
}
// Rich-markdown → старый Markdown v1 (там жирный — ОДНА звёздочка, заголовков/таблиц/спойлеров нет).
function tgMdToLegacy(md) {
  return String(md == null ? '' : md)
    .replace(/^\s{0,3}#{1,6}\s+(.+)$/gm, '*$1*')          // # Заголовок → жирная строка
    .replace(/\*\*([\s\S]+?)\*\*/g, '*$1*')               // **жирный** → *жирный*
    .replace(/==([\s\S]+?)==/g, '$1')                     // маркер — нет такого
    .replace(/\|\|([\s\S]+?)\|\|/g, '$1')                 // спойлер — нет такого
    .replace(/^\s{0,3}(?:---|\*\*\*|___)\s*$/gm, '—');    // разделитель
}
// Совсем голый текст — последняя ступень, когда даже v1 не принял (непарные символы в ответе модели).
function tgMdPlain(md) {
  return String(md == null ? '' : md)
    .replace(/^\s{0,3}#{1,6}\s+/gm, '')
    .replace(/\*\*([\s\S]+?)\*\*/g, '$1').replace(/==([\s\S]+?)==/g, '$1').replace(/\|\|([\s\S]+?)\|\|/g, '$1')
    .replace(/^\s{0,3}(?:---|\*\*\*|___)\s*$/gm, '—');
}
// Лестница отправки: rich → Markdown v1 → голый текст. Каждая ступень ниже по красоте, но выше по
// надёжности. Если сервер не знает rich (старый Bot API у Telegram/самохост) — нода запоминает это
// причину в статус и в Консоль — и всё равно пробует снова на следующем ответе. Возвращает ответ Telegram + чем ушло.
// Журнал последней попытки богатой разметки (на диск): что за метод, чем кончилось, почему.
// Нужен, чтобы разбирать «пришло старым форматом» по факту, а не по догадкам.
function tgRichLog(step, ok, why, extra) {
  try {
    const prev = lsGet('rlm.rich.log', []) || [];
    prev.push(Object.assign({ step, ok: !!ok, why: why ? String(why).slice(0, 200) : '' }, extra || {}));
    lsSet('rlm.rich.log', prev.slice(-20));   // держим последние 20 записей
  } catch (_) { /* журнал не критичен */ }
}
async function tgSendPretty(el, token, chatId, md, threadId, extra) {
  {
    const r = await tgSendRich(token, chatId, md, threadId, extra);
    tgRichLog('sendRichMessage', r && r.ok, (r && r.description) || '', { len: (md || '').length, hasKb: !!(extra && extra.reply_markup), thread: threadId == null ? null : threadId });
    if (r && r.ok) return Object.assign({}, r, { rich: true });
    const why = String((r && r.description) || 'без описания');
    if (el && el._setStatus) el._setStatus('⚠ богатая разметка не прошла: ' + why + ' — шлю попроще', 'err');   // молчать нельзя: иначе непонятно, почему таблица приходит текстом
    try { consoleLog('sendRichMessage', { error: why }); } catch (_) { /* консоль опциональна */ }
  }
  const r2 = await tgSendMessage(token, chatId, tgMdToLegacy(md), threadId, 'Markdown', extra);
  if (r2 && r2.ok) return Object.assign({}, r2, { rich: false });
  return Object.assign({}, await tgSendMessage(token, chatId, tgMdPlain(md), threadId, undefined, extra), { rich: false });
}
// Та же лестница для правки на месте (ручной фидбек критика). wasRich — чем это сообщение уходило:
// rich правится только rich-ом, обычное — только обычным (иначе Telegram не примет).
async function tgEditPretty(el, token, chatId, messageId, md, wasRich, extra) {
  if (wasRich) return await tgEditRich(token, chatId, messageId, md, extra);
  const r = await tgEditMessage(token, chatId, messageId, tgMdToLegacy(md), 'Markdown', extra);
  if (r && r.ok) return r;
  return await tgEditMessage(token, chatId, messageId, tgMdPlain(md), undefined, extra);
}
const tgSendTyping = (token, chatId, threadId) => tgCall(token, 'sendChatAction', Object.assign({ chat_id: chatId, action: 'typing' }, threadId != null ? { message_thread_id: threadId } : {}));
// Отправка аудио-файла (base64) в Telegram — multipart/form-data (не JSON!). voice = голосовое
// сообщение (нужен OGG/OPUS), audio = обычный аудиофайл (WAV/MP3). Возвращает { ok, ... }.
async function tgSendAudioFile(token, chatId, b64, kind /* 'voice'|'audio' */, mime, filename, threadId, extra) {
  try {
    const bytes = Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));
    const fd = new FormData();
    fd.append('chat_id', String(chatId));
    if (threadId != null) fd.append('message_thread_id', String(threadId));
    // подпись/кнопки к голосовому: у sendVoice есть caption (до 1024 символов), parse_mode и reply_markup —
    // значит текст и голос помещаются в ОДНО сообщение, а не в два.
    Object.entries(extra || {}).forEach(([k, v]) => { if (v != null) fd.append(k, typeof v === 'string' ? v : JSON.stringify(v)); });
    fd.append(kind, new Blob([bytes], { type: mime }), filename);
    const res = await fetch(TG_API + token + '/' + (kind === 'voice' ? 'sendVoice' : 'sendAudio'), { method: 'POST', body: fd });
    return await res.json();
  } catch (e) {
    return { ok: false, description: String((e && e.message) || e) };
  }
}
// Нода «Озвучка», подключённая к нижней ножке «Озвучка» ноды Telegram (Telegram.out:tts → Озвучка.вход).
// СТРОГО по проводу (без фолбэка на любую ноду) — голос включаем, только если пользователь подключил явно.
function ttsNodeForTelegram(el) {
  const out = findPort(el, 'out:tts');
  const conn = out && connections.find((c) => c.from === out && c.to.closest('.node-tts'));
  return conn ? conn.to.closest('.node-tts') : null;
}
// Дождаться готовности модели озвучки (первая загрузка — минуты): поднять (ensure) и опрашивать health,
// пока не ready. Так первый голосовой (и старт) НЕ падают в текст, пока модель грузится. Реальная
// ошибка / нет сервиса / таймаут → false (звонящий уйдёт в текст).
async function tgTtsWaitReady(el, maxMs) {
  maxMs = maxMs || 300000;   // до 5 минут на первую загрузку
  if (!(window.rlm && window.rlm.tts)) { el._setStatus('⚠ сервис озвучки не поднят — шлю текстом', 'err'); return false; }
  try { await window.rlm.tts.ensure(); } catch (e) { /* поднимем/дождёмся по health */ }
  const startMs = Date.now();
  while (true) {
    let h = null;
    try { h = await window.rlm.tts.health(); } catch (e) { h = null; }
    if (h && h.ready) return true;
    if (h && h.error && !/груз/i.test(h.error)) { el._setStatus('⚠ озвучка: ' + h.error + ' — шлю текстом', 'err'); return false; }
    let pct = '';
    try { const pr = await window.rlm.tts.progress(); if (pr && pr.phase === 'load') pct = ' ' + Math.round((pr.value || 0) * 100) + '%'; } catch (e) { /* нет прогресса */ }
    el._setStatus('🎙 поднимаю модель озвучки…' + pct, '');
    if (Date.now() - startMs > maxMs) { el._setStatus('⚠ модель озвучки долго грузится — шлю текстом', 'err'); return false; }
    await tgSleep(1500);
  }
}
// Озвучить ответ и отправить голосовым. true — ушло голосом; false — не смогли (звонящий шлёт текстом).
async function telegramSendVoice(el, token, chatId, text, threadId, opts) {
  const tts = ttsNodeForTelegram(el);
  if (!tts) { el._setStatus('⚠ голос: подключи ноду «Озвучка» к ножке снизу', 'err'); return false; }
  const src = ttsVoiceSource(tts);   // клон по образцу или генератор по описанию
  if (src.mode === 'clone' && !src.ref) { el._setStatus('⚠ голос: в «Озвучке» выбери образец (WAV)', 'err'); return false; }
  if (src.mode === 'design' && !src.instruct) { el._setStatus('⚠ голос: в «Озвучке» задай черты голоса (генератор)', 'err'); return false; }
  if (!(await tgTtsWaitReady(el))) return false;   // галочка «голосом» стоит → ЖДЁМ загрузку модели, не падаем в текст пока грузится
  // Текст для модели: развернуть макросы + снять разметку (*, кавычки) — чтобы не читала звёздочки.
  let clean = substituteMacros(text || '').replace(/\*+/g, '').replace(/[«»“”]/g, '"').trim();
  if (!clean) return false;
  // Тегетирование (опция ноды «Озвучка»): API берём из ноды, подключённой ко входу Telegram (как telegramReply).
  if ((tts.querySelector('.tts-tagging') || {}).checked) {
    try {
      const chatIn = el.querySelector(':scope > .port.in');
      const apiConn = connections.find((c) => c.to === chatIn && c.from.closest('.node-api'));
      const apiEl = apiConn ? apiConn.from.closest('.node-api') : null;
      if (apiEl) {
        const base = (apiEl.querySelector('.f-base') || {}).value ? apiEl.querySelector('.f-base').value.trim() : '';
        const key = (apiEl.querySelector('.f-key') || {}).value || '';
        const model = (apiEl.querySelector('.f-model') || {}).value ? apiEl.querySelector('.f-model').value.trim() : '';
        if (base && model) { el._setStatus('🏷 расставляю теги…', ''); clean = await ttsAutoTag(tts, { base, key, model }, clean); }
      }
    } catch (e) { /* фолбэк — озвучиваем без тегов */ }
  }
  el._setStatus('🎙 озвучиваю ответ…', '');
  if (token) await tgSendTyping(token, chatId, threadId);
  // Просим OGG/OPUS — это то, что Telegram примет как голосовое (sendVoice). Сервис сам поднимет модель
  // и проверит готовность; не готова (грузится) → вернёт ошибку, и мы уйдём в текст этим ответом.
  let r;
  try {
    const payload = { text: clean, params: readTtsParams(tts), fmt: 'ogg' };
    if (src.mode === 'design') payload.instruct = src.instruct;   // генератор по описанию — без образца
    else { payload.ref_audio = src.ref; payload.ref_text = ((tts.querySelector('.tts-reftext') || {}).value || '').trim(); }
    r = await window.rlm.tts.generate(payload);
  } catch (e) { r = { ok: false, error: String((e && e.message) || e) }; }
  if (!r || !r.ok || !r.audioB64) { el._setStatus('⚠ голос: ' + ((r && r.error) || 'ошибка озвучки') + ' — шлю текстом', 'err'); return false; }
  if (opts && opts.renderOnly) return { b64: r.audioB64, fmt: r.fmt };   // вернуть озвучку, отправит вызывающий (вложит в общее сообщение)
  // OGG/OPUS → голосовое (sendVoice); фолбэк WAV (Opus не собрался в сервисе) → обычное аудио (sendAudio).
  const asVoice = r.fmt === 'ogg';
  // Подпись к голосовому: rich-разметку caption не понимает — сводим к Markdown v1, а при отказе шлём голый текст.
  const cap = (opts && opts.caption) ? String(opts.caption) : '';
  const kb = (opts && opts.reply_markup) ? opts.reply_markup : null;
  const mk = (plain) => Object.assign({},
    cap ? { caption: plain ? tgMdPlain(cap) : tgMdToLegacy(cap) } : {},
    (cap && !plain) ? { parse_mode: 'Markdown' } : {},
    kb ? { reply_markup: kb } : {});
  let sent = asVoice
    ? await tgSendAudioFile(token, chatId, r.audioB64, 'voice', 'audio/ogg', 'voice.ogg', threadId, mk(false))
    : await tgSendAudioFile(token, chatId, r.audioB64, 'audio', 'audio/wav', 'voice.wav', threadId, mk(false));
  if (cap && !(sent && sent.ok)) {   // подпись не прошла разметкой → тот же голос, но текстом без разметки
    sent = asVoice
      ? await tgSendAudioFile(token, chatId, r.audioB64, 'voice', 'audio/ogg', 'voice.ogg', threadId, mk(true))
      : await tgSendAudioFile(token, chatId, r.audioB64, 'audio', 'audio/wav', 'voice.wav', threadId, mk(true));
  }
  if (sent && sent.ok) return { ok: true, messageId: ((sent.result || {}).message_id != null ? sent.result.message_id : null) };   // id нужен, чтобы правка по фидбеку могла снести это голосовое
  el._setStatus('⚠ голос не ушёл: ' + ((sent && sent.description) || 'ошибка') + ' — шлю текстом', 'err');
  return false;
}
// Индикатор модели озвучки в ноде Telegram (общий сервис 8123): дот+подпись, при загрузке — %.
// Самоочистка таймера, когда нода удалена с холста.
async function tgModelHealth(el) {
  if (!el.isConnected) return;   // ещё не на холсте (восстановление) или уже удалена — пропустить тик (таймер чистит removeNode)
  const dot = el.querySelector('.tg-tts-model .tts-model-dot');
  const txt = el.querySelector('.tg-tts-model .tts-model-txt');
  if (!dot || !txt) return;
  let h = null;
  try { h = (window.rlm && window.rlm.tts) ? await window.rlm.tts.health() : null; } catch (e) { /* сервис не поднят */ }
  let state = 'off', label = 'не запущена';
  if (h && h.ready) { state = 'ready'; label = 'готова' + (h.cuda ? ' · GPU' : ' · CPU') + (h.dtype ? ' · ' + h.dtype : ''); }
  else if (h && h.error && !/груз/i.test(h.error)) { state = 'err'; label = 'ошибка'; }
  else if (h) {
    state = 'load'; label = 'грузится…';
    try { const pr = await window.rlm.tts.progress(); if (pr && pr.phase === 'load') label = 'грузится… ' + Math.round((pr.value || 0) * 100) + '%'; } catch (e) { /* нет прогресса */ }
  }
  dot.dataset.state = state; txt.textContent = 'модель: ' + label;
}
// Строка консоли-лога: «Ник: сообщение». Собеседник — приглушённый ник, персонаж (out) — акцентный.
// Переносы в тексте сохраняются (CSS white-space: pre-wrap), разметку не трогаем — чистый лог.
// ── Разметка сцен прямо в ленте (Хроника) — как в сингле: каретки ►◄ на сообщении, подпись сцены,
//    призраки свёрнутых. Лента показывает и то, чего в истории ещё нет (реплики-кандидаты хода),
//    поэтому строки сопоставляем с историей по порядку И по роли: «out» ↔ char, «in» ↔ user.
function tgActiveConvo(el) {
  const cid = (typeof tgTargetChat === 'function') ? tgTargetChat(el) : el._lastChatId;
  return (cid != null) ? (el._convos || {})[cid] : null;
}
function tgSceneMsgs(el) { const c = tgActiveConvo(el); return c ? (c.msgs || []).filter((m) => m.role === 'user' || m.role === 'char') : []; }
// Отметить начало/конец сцены (повторный клик по той же каретке — снять).
function tgSceneMark(el, which, idx) {
  const sc = el._scene = el._scene || { start: null, end: null };
  sc[which] = (sc[which] === idx) ? null : idx;
  if (el._setStatus) {
    const done = sc.start != null && sc.end != null;
    el._setStatus(done ? 'сцена отмечена — жми «Собрать сцену»' : (sc.start == null ? 'отметь НАЧАЛО сцены ►' : 'отметь КОНЕЦ сцены ◄'), done ? 'ok' : '');
  }
  tgSyncSceneUI(el);
}
// Полоска сцены в одном сообщении: каретки + подпись сцены/призрак. Строится один раз, дальше — обновляется.
function tgSceneRowUI(el, row, m, idx, sc, lo, hi) {
  const bub = row.querySelector('.tg-bub'); if (!bub) return;
  let bar = bub.querySelector(':scope > .tg-scene-bar');
  const numOld = bub.querySelector(':scope > .tg-num');
  if (idx == null) { if (bar) bar.remove(); if (numOld) numOld.remove(); row.classList.remove('tg-ghost', 'tg-in-scene'); delete row.dataset.h; return; }
  row.dataset.h = String(idx);
  // Номер сообщения в уголке пузыря: по нему заданы окна событий Режиссёра и прыжки из «Оглавления».
  const num = numOld || (() => { const n = document.createElement('span'); n.className = 'tg-num'; bub.appendChild(n); return n; })();
  num.textContent = '#' + idx;
  num.title = 'Сообщение #' + idx + ' в истории — этим номером считаются окна событий и прыжки из оглавления';
  row.classList.toggle('tg-ghost', !!m.chrHidden);
  row.classList.toggle('tg-in-scene', lo != null && idx >= lo && idx <= hi);
  if (!bar) {
    bar = document.createElement('span'); bar.className = 'tg-scene-bar';
    bar.innerHTML = '<button class="tg-sc-btn tg-sc-start" type="button" title="Отметить НАЧАЛО сцены">►</button>'
      + '<button class="tg-sc-btn tg-sc-end" type="button" title="Отметить КОНЕЦ сцены">◄</button>'
      + '<span class="tg-sc-tag"></span>';
    bub.insertBefore(bar, bub.firstChild);
    bar.querySelectorAll('.tg-sc-btn').forEach((b) => b.addEventListener('pointerdown', (e) => e.stopPropagation()));
    bar.querySelector('.tg-sc-start').addEventListener('click', (e) => { e.stopPropagation(); tgSceneMark(el, 'start', Number(row.dataset.h)); });
    bar.querySelector('.tg-sc-end').addEventListener('click', (e) => { e.stopPropagation(); tgSceneMark(el, 'end', Number(row.dataset.h)); });
  }
  bar.querySelector('.tg-sc-start').classList.toggle('on', !!sc && sc.start === idx);
  bar.querySelector('.tg-sc-end').classList.toggle('on', !!sc && sc.end === idx);
  const tag = bar.querySelector('.tg-sc-tag');
  const parts = [];
  if (m.chrScene) parts.push('🗒 ' + (m.chrScene.name || ('Сцена ' + (m.chrScene.num || ''))));
  if (m.chrHidden) parts.push('👻');
  tag.textContent = parts.join('  ');
  tag.title = m.chrHidden ? 'Свёрнуто в Хронику — в контекст модели не идёт' : (m.chrScene ? 'Сцена, в которую свёрнуто это сообщение' : '');
}
// Пере-навести разметку на всю ленту (после нового сообщения, перерисовки, записи сцены).
function tgSyncSceneUI(el) {
  const feed = el && el.querySelector && el.querySelector('.tg-feed'); if (!feed) return;
  const msgs = tgSceneMsgs(el);
  const sc = el._scene || null;
  const both = !!(sc && sc.start != null && sc.end != null);
  const lo = both ? Math.min(sc.start, sc.end) : null;
  const hi = both ? Math.max(sc.start, sc.end) : null;
  let j = 0;
  [...feed.querySelectorAll('.tg-line:not(.tg-cand)')].forEach((row) => {
    const want = row.classList.contains('out') ? 'char' : 'user';
    while (j < msgs.length && msgs[j].role !== want) j++;   // строки, которых нет в истории, пропускаем
    const m = (j < msgs.length) ? msgs[j] : null;
    const idx = m ? j : null; if (m) j++;
    tgSceneRowUI(el, row, m, idx, sc, lo, hi);
  });
  const btn = el.querySelector('.tg-ng-scene');
  if (btn) btn.style.display = both ? '' : 'none';   // «Собрать сцену» — только при отмеченной ►◄ разметке
}
// «Собрать сцену»: движок Хроники тот же, что в сингле, только историю ему подставляем из активной беседы
