async function tgYandexRu(text) {
  const t = String(text || '').trim();
  if (!t) return '';
  if (!/[a-z]/i.test(t)) return t;                       // и так по-русски — незачем гонять
  try {
    const r = await rlmApi('/api/rlm/translate', { provider: 'yandex', text: t, to: 'ru' });
    return (r && r.ok && r.text) ? r.text : t;
  } catch (e) { return t; }
}
// «Бот не уснул»: пока идёт ход, в чате висит одно сообщение со смешной фразой. Оно молча правится
