// однотипными «Лорбук · …» и нужное приходится выискивать глазами.
const TG_VIS_GROUP_NAME = { lorebook: 'Лорбук', sysprompt: 'Системный промт', soul: 'Душа', state: 'Состояние',
  character: 'Персонаж', persona: 'Персона', api: 'API', critic: 'Критик', chronicle: 'Хроника', tts: 'Озвучка',
  objective: 'Цель', dry: 'DRY', director: 'Режиссёр', translator: 'Транслитер', embedder: 'Эмбеддер' };
