      + '<button class="tg-md-b" data-md="i" type="button" title="Курсив"><i>К</i></button>'
      + '<button class="tg-md-b" data-md="q" type="button" title="Цитата">&gt;</button>'
      + '<button class="tg-md-b" data-md="l" type="button" title="Список">•</button>'
      + '<button class="tg-md-b" data-md="s" type="button" title="Спойлер">▨</button>'
