    ta.scrollIntoView({ block: 'nearest' });
    const restore = (html) => { const sp = document.createElement('span'); sp.className = 'tg-txt tg-md'; sp.innerHTML = html; ta.replaceWith(sp); bar.remove(); row.classList.remove('tg-editing'); row._editing = false; };
