// Запуск: проверить токен (getMe), пропустить накопленное за время простоя, крутить polling.
// Перехват опроса: занять бота под ЭТУ ноду перед стартом. «Последний getUpdates выигрывает»,
// поэтому: гасим другие ноды Telegram с тем же токеном в приложении, снимаем вебхук (+сброс очереди)
// и несколько раз дёргаем getUpdates — это выбивает залипший чужой опрос (закрытая вкладка/старый старт).
// Против ЖИВОГО второго экземпляра (другое окно/сервер) не поможет — такой надо закрыть вручную.
async function tgTakeover(el, token) {
  document.querySelectorAll('.node-telegram').forEach((n) => {
    if (n === el) return;
    const t = ((n.querySelector('.tg-token') || {}).value || '').trim();
    if (t && t === token && n._running) {
      n._running = false;
      n.querySelectorAll('.tg-run').forEach((rb) => tgBtnLabel(rb, 'Запустить бота'));   // кнопка дублируется (верх ноды + настройки) — подпись у обеих
      if (n._setStatus) n._setStatus('остановлен (перехват другой нодой)', '');
    }
  });
  await tgCall(token, 'deleteWebhook', { drop_pending_updates: true });   // снять вебхук + сбросить очередь
  let ok = false, desc = '';
  for (let i = 0; i < 3; i++) {
    const r = await tgCall(token, 'getUpdates', { offset: -1, timeout: 0 });   // «выбить» чужой залипший опрос
    if (r && r.ok) { ok = true; if (r.result.length) el._tgOffset = r.result[r.result.length - 1].update_id + 1; break; }
    desc = (r && r.description) || '';
    await tgSleep(700);
  }
  return { ok, desc };
}
async function tgStart(el, token) {
  el._setStatus('проверяю токен…', '');
  const me = await tgCall(token, 'getMe');
  if (!me || !me.ok) { el._setStatus('✗ ' + ((me && me.description) || 'токен не принят'), 'err'); return; }
  el._botId = me.result.id;
  el._botName = me.result.username || me.result.first_name;
  // Перехват: занять бота под эту ноду (гасит дубли в приложении, снимает вебхук, выбивает залипший опрос).
  el._setStatus('перехват опроса…', '');
  const tk = await tgTakeover(el, token);
  if (!tk.ok && /conflict/i.test(tk.desc)) {   // не смогли перехватить → где-то ЖИВОЙ второй слушатель
    el._setStatus('✗ бот уже запущен где-то ещё (другое окно/копия/сервер) — закрой его и жми снова', 'err');
    return;
  }
  el._running = true;
  el._setStatus('@' + el._botName + ' · слушаю…', 'ok');
  tgPollLoop(el, token);                        // крутится фоном (не await)
}
// Цикл long polling: тянет апдейты, двигает offset, отдаёт каждый в обработчик.
async function tgPollLoop(el, token) {
  while (el._running) {
    const r = await tgCall(token, 'getUpdates', { offset: el._tgOffset, timeout: 25 });
    if (!el._running) break;                    // остановили, пока ждали ответа
    if (!r || !r.ok) { el._setStatus('✗ ' + ((r && r.description) || 'связь'), 'err'); await tgSleep(3000); continue; }
    for (const u of r.result) {
      el._tgOffset = u.update_id + 1;
      await tgHandleUpdate(el, token, u);
    }
  }
}
// Обработка одного апдейта. Личка → отвечаем всегда; группа → копим контекст, отвечаем на обращённое.
async function tgHandleUpdate(el, token, u) {
  if (u.callback_query) return tgHandleCallback(el, token, u.callback_query);   // нажата кнопка под сообщением — отдельный тип события
  const msg = u.message || u.edited_message;
  if (!msg) return;
  const isEdit = !u.message && !!u.edited_message;   // сообщение отредактировано в Telegram
  const chatId = msg.chat.id;
  const threadId = (msg.message_thread_id != null) ? msg.message_thread_id : null;   // номер темы форума (null — обычный чат/General)
  const tgMode = (el.querySelector('.tg-mode') || {}).value || 'dm';
  const chatTitle = (msg.chat && (msg.chat.title || msg.chat.first_name || msg.chat.username)) || ('чат ' + chatId);
  tgSeeChat(el, chatId, chatTitle);   // выпадашка «Чат» знает ВСЕ чаты (даже те, что зафиксированы мимо — чтобы можно было переключиться)
  if (el._chatFilter != null && String(chatId) !== String(el._chatFilter)) return;   // бот зафиксирован на ДРУГОМ чате — игнорируем это сообщение
  // Форум-темы: запомнить тему (имя — из служебного сообщения о создании/правке) + номер последней темы (для «🔒 текущая»).
  if (threadId != null) {
    // Имя темы Telegram присылает не в каждом сообщении: при создании и правке — прямо в сообщении,
    // а в обычной реплике — внутри reply_to_message (сервисное сообщение о создании темы).
    const rt = msg.reply_to_message || {};
    const tname = (msg.forum_topic_created && msg.forum_topic_created.name)
      || (msg.forum_topic_edited && msg.forum_topic_edited.name)
      || (rt.forum_topic_created && rt.forum_topic_created.name)
      || (rt.forum_topic_edited && rt.forum_topic_edited.name)
      || null;
    tgSeeTopic(el, threadId, tname);
    // «Последняя тема» запоминается ТОЛЬКО из своей темы: иначе болтовня в соседней теме
    // переписывала _lastThreadId, и следующий ход бота уходил туда (утечка в чужую тему).
    if (el._topicFilter == null || threadId === el._topicFilter) el._lastThreadId = threadId;
  }
  if (!msg.text) return;                          // дальше — только текстовые сообщения
  if (msg.from && msg.from.is_bot) return;        // не реагируем на других ботов (анти-петля)
  if (tgMode === 'group' && el._topicFilter != null && threadId !== el._topicFilter) return;   // читаем ТОЛЬКО выбранную тему форума
  el._lastChatId = chatId;                        // запомнить чат — для кнопки «Написать самому»
  const from = (msg.from && (msg.from.first_name || msg.from.username)) || 'кто-то';
  const authorId = (tgMode === 'group') ? ('tg:' + ((msg.from && msg.from.id) || from)) : null;   // id участника — для mute/цвета/розетки
  // Заводим участника СРАЗУ (до вычисления `muted`): иначе его ПЕРВАЯ реплика проскакивает в контекст,
  // пока он ещё не появился в касте заглушённым. Сетевая игра: новый = 🔇 по умолчанию (tgEnsureParticipant: muted=isNg),
  // активируется ТОЛЬКО через панель («Это персонаж»). Обычную группу Telegram это не меняет (там новый — активен).
  if (authorId) tgEnsureParticipant(el, authorId, from);
  const muted = !!(authorId && el._castById && el._castById[authorId] && el._castById[authorId].muted);
  if (isEdit && !el.classList.contains('node-netgame')) return;   // правку обрабатывает только сетевая игра; сингл/групп — как раньше (игнор)
  if (!isEdit && !el.classList.contains('node-netgame')) tgFeed(el, msg.text, 'in', from, { muted, authorId, msgId: msg.message_id });   // netgame рисует свою строку-кандидат ниже (с чекбоксом выбора)
  // Авто-перевод ВВОДА RU→EN: в модель уходит английский, в консоль/Telegram — русский оригинал.
  // Перевод не удался → берём оригинал (безопасный фолбэк). Секция «replace» = RU→EN (как кнопка EN).
  let forModel = msg.text;
  // Сетевая игра: перевод НЕ при получении, а на «Собрать ход» (tgNgSendTurn) — копим сырой текст. Личка/группа — как раньше.
  if (tgAutoTr(el) && !el.classList.contains('node-netgame')) { const t = await tgTranslateRetry(msg.text, 'en', 'replace'); if (t != null) forModel = t; else el._setStatus('⚠ перевод входящего не удался — в модель ушёл оригинал', 'err'); }
  const mode = (el.querySelector('.tg-mode') || {}).value || 'dm';
  if (mode === 'group') {
    // Копим ВСЮ переписку группы как контекст (реплика подписана именем автора, чтобы персонаж
    // различал людей). Отвечаем ТОЛЬКО когда бота @упомянули или ответили (reply) на его сообщение.
    const convo = el._convos[chatId] || (el._convos[chatId] = { chatId: (typeof chatIdBase === 'function' && el._chatId ? chatIdBase(el._chatId) : genChatId()), msgs: [] });
    // участник уже заведён выше — до вычисления `muted` (чтобы первая реплика нового не проскочила в контекст)
    if (el.classList.contains('node-netgame')) {
      // СЕТЕВАЯ ИГРА: реплики живых игроков КОПЯТСЯ в буфер хода (ник → костюм-персона); склейка в одно
      // {{user}} — по обращению к боту (@/reply) ИЛИ по кнопке «Собрать ход» в ноде. Сингл/групп — ветка ниже.
      if (isEdit) { tgNgEditPending(el, msg.message_id, msg.text); return; }   // правка в Telegram → обновить СЫРОЙ текст (перевод — на «Собрать ход»)
      const pp = el._castById && el._castById[authorId];
      const active = tgNgActive(el, pp);   // активен = НЕ заглушён И ряд готов (Персона+Душа+Состояние подключены)
      const persona = (typeof tgBoundName === 'function' && tgBoundName(pp)) || from;   // имя ПЕРСОНЫ (костюм), иначе — настоящий ник
      // в ленте: имя персоны если есть; нет персоны/не активен → настоящий ник СЕРЫМ (значит не в игре, в ход не идёт)
      tgFeed(el, msg.text, 'in', active ? persona : from, active
        ? { authorId, msgId: msg.message_id, cand: { authorId, persona, text: msg.text, msgId: msg.message_id } }
        : { muted: true, authorId, msgId: msg.message_id });
      if (active && tgIsAddressed(el, msg)) await tgNgSendTurn(el, token, chatId, threadId);
      return;
    }
    if (!muted) tgAddMsg(el, convo, { role: 'user', text: from + ': ' + forModel, authorId });   // заглушённого в ИСТОРИЮ не пишем (в логе он виден серым)
    if (!muted && tgIsAddressed(el, msg)) await telegramReply(el, token, chatId, null, threadId);   // заглушённый НЕ будит бота (даже @упоминанием/reply)
    return;
  }
  await telegramReply(el, token, chatId, forModel, threadId);
}
// Включён ли авто-перевод (RU↔EN) в ноде Telegram.
function tgAutoTr(el) { return !!(el.querySelector('.tg-auto-tr') || {}).checked; }
// Перевод для бота с ОДНИМ ретраем: переводчик (нейро/сервис) при лимите/затыке молча отдаёт null,
// а бот тогда шлёт оригинал — «не переводится». Пауза + повтор ловит транзиентные сбои. null — не вышло и после повтора.
async function tgTranslateRetry(text, to, mode) {
  let t = await trTranslate(text, to, mode);
  if (t == null) { await tgSleep(700); t = await trTranslate(text, to, mode); }
  return t;
}

// Адресовано ли сообщение боту: reply на его сообщение ИЛИ @упоминание его username в тексте.
function tgIsAddressed(el, msg) {
  if (msg.reply_to_message && msg.reply_to_message.from && msg.reply_to_message.from.id === el._botId) return true;
  const uname = (el._botName || '').toLowerCase();
  return !!uname && (msg.text || '').toLowerCase().includes('@' + uname);
}

// ── СЕТЕВАЯ ИГРА: сбор хода нескольких живых игроков в ОДНО {{user}} (только нода «Сетевая игра») ──
// Комплитер, кормящий эту ноду (netgame.вход ← API ← комплитер).
function tgNgCompleter(el) {
  const inP = el.querySelector(':scope > .port.in'); if (!inP) return null;
  const c = connections.find((x) => x.to === inP && x.from.closest && x.from.closest('.node-api'));
  const api = c ? c.from.closest('.node-api') : null;
  return api ? completerForApi(api) : null;
}
// Слот мультипользователя этого комплитера (или null).
function tgNgMuser(el) { const comp = tgNgCompleter(el); return comp ? comp.querySelector('.pm-item.pm-muser') : null; }
// Карточка-движок ({{char}}), кормящая комплитер этой ноды (её поля → плашки комплитера). Фолбэк — любой Персонаж.
function tgNgCharNode(el) {
  const comp = tgNgCompleter(el);
  if (comp) { const c = connections.find((cc) => cc.to && cc.to.closest && cc.to.closest('.node-prompt, .node-mprompt') === comp && cc.from && cc.from.closest && cc.from.closest('.node-char')); if (c) return c.from.closest('.node-char'); }
  return document.querySelector('.node-char');
}
// Имя костюма (персоны) игрока: позиция участника = позиция ряда слота → имя подключённой ноды Персона; фолбэк — имя ряда/ник.
function tgNgPersonaName(el, authorId, fallback) {
  const mu = tgNgMuser(el); if (!mu) return fallback;
  // ТОЛЬКО явная связь по data-author (кнопка «Это персонаж»). Позиционного фолбэка НЕТ:
  // он вешал реплику на чужой ряд по номеру в касте → «ник перелетал» на другого игрока/персону.
  const row = [...mu.querySelectorAll('.pm-mu-row')].find((r) => r.dataset.author === authorId);
  if (!row) return fallback;   // не привязан → своим ником, чужую персону не подставляем
  return muRowPersonaName(row) || fallback;
}
// «Это персонаж»: разглушить участника + завести ему ряд в слоте мультипользователя (связь по authorId)
// + создать и подключить Персону/Душу/Состояние. Ряд ищем: уже связанный → свободный пустой → новый.
function tgNgMakeCharacter(el, p) {
  if (!p) return;
  p.muted = false; tgSyncPartRow(el, p);   // разглушить участника
  if (typeof persistCurrentGraph === 'function') persistCurrentGraph();   // и сразу в снимок: иначе при следующем заходе он снова «вне контекста»
  const feed = el.querySelector('.tg-feed'); if (feed) feed.querySelectorAll('.tg-line[data-author="' + p.id + '"]').forEach((r) => r.classList.remove('muted'));
  const mu = tgNgMuser(el);
  if (!mu) { if (el._setStatus) el._setStatus('нет слота мультипользователя в комплитере', 'err'); return; }
  const rows0 = [...mu.querySelectorAll('.pm-mu-row')];
  const nick = (p.name || '').trim().toLowerCase();
  // имя ряда = имя ПОДКЛЮЧЁННОЙ персоны, иначе имя ряда (.pm-mu-nm)
  const rowName = (r) => {
    const port = r.querySelector('.port.in[data-field="persona"]');
    const conn = port && connections.find((c) => c.to === port && c.from.closest && c.from.closest('.node-persona, .node-char'));
    if (conn) { const nm = ((conn.from.closest('.node-persona, .node-char').querySelector('.ch-name-input') || {}).value || '').trim(); if (nm && nm !== 'User') return nm; }
    return ((r.querySelector('.pm-mu-nm') || {}).textContent || '').trim();
  };
  // Ряд: уже привязанный к ЭТОМУ участнику → ИНАЧЕ ряд, чья персона/имя СОВПАДАЕТ с ником участника (автоподбор по имени) →
  //      ИНАЧЕ первый свободный пустой ряд → ИНАЧЕ новый.
  let row = rows0.find((r) => r.dataset.author === p.id)
    || (nick && rows0.find((r) => !r.dataset.author && rowName(r).toLowerCase() === nick))
    || rows0.find((r) => !r.dataset.author && !((r.querySelector('.pm-mu-nm') || {}).textContent || '').trim());
  if (!row) { const add = mu.querySelector('.mu-add-row'); if (add) add.click(); const r1 = mu.querySelectorAll('.pm-mu-row'); row = r1[r1.length - 1]; }
  if (!row) return;
  row.dataset.author = p.id;   // связать ряд с участником Telegram
  const nm = row.querySelector('.pm-mu-nm');
  if (nm && !nm.textContent.trim()) { nm.textContent = p.name || ''; const a = row.querySelector('.mu-ava'); if (a) a.textContent = (p.name || '＋').slice(0, 1); }
  const soulPort = row.querySelector('.port.in[data-field="soul"]');   // ноды уже есть?
  const hasNodes = soulPort && connections.some((c) => c.to === soulPort);
  if (!hasNodes && typeof muCreateNodesForRow === 'function') muCreateNodesForRow(row);
  else if (hasNodes) {
    // Ноды у ряда уже стоят (создавались раньше) — Душу всё равно ставим на набор «игрок»,
    // если её ещё не переключали (иначе ручные правки набора остались бы затёрты).
    const sc = connections.find((c) => c.to === soulPort && c.from.closest && c.from.closest('.node-soul'));
    const soul = sc ? sc.from.closest('.node-soul') : null;
    if (soul && soul._promptMode !== 'player' && typeof applyNetgameSoulDocs === 'function') applyNetgameSoulDocs(soul);
  }
  redrawWires();
  if (typeof persistCurrentGraph === 'function') persistCurrentGraph();   // СОХРАНИТЬ привязку персоны к игроку — иначе слетает при заходе в сохранённую сессию
}
// Накопить реплику игрока в буфер текущего хода (ник подменён на костюм-персону). msgId — id сообщения Telegram (для правок).
function tgNgAccum(el, authorId, from, text, msgId) {
  const persona = tgNgPersonaName(el, authorId, from);
  (el._ngTurn = el._ngTurn || []).push({ authorId, persona, text, msgId });
  if (typeof persistCurrentGraph === 'function') persistCurrentGraph();   // реплика в ход — сразу в снимок (написанное до старта не должно пропадать)
  tgNgRenderPending(el);
}
// Правка сообщения в Telegram → обновить его текст в буфере хода (по id сообщения), перерисовать сборку.
function tgNgEditPendingSave(el) { try { if (typeof persistCurrentGraph === 'function') persistCurrentGraph(); } catch (_) {} }
function tgNgEditPending(el, msgId, newText) {
  const entry = (el._ngTurn || []).find((t) => t.msgId != null && t.msgId === msgId);
  if (entry) { entry.text = newText; tgNgRenderPending(el); tgNgEditPendingSave(el); }   // текст заявки правился только в памяти — после перезахода откатывался
}
// Показать «ход в сборке»: реплики буфера до «Собрать ход», у каждой крестик (удалить из хода).
function tgNgRenderPending(el) {
  const turn = el._ngTurn || [];
  const btn = el.querySelector('.tg-ng-send');
  if (btn) {   // счётчик — и в подпись, и бейджем в углу значка (кнопка под лентой — только значок)
    tgBtnLabel(btn, turn.length ? ('Собрать ход (' + turn.length + ')') : 'Собрать ход');
    if (turn.length) btn.dataset.n = String(turn.length); else delete btn.dataset.n;
    btn.title = turn.length ? ('Собрать ход · реплик в сборке: ' + turn.length) : 'Склеить накопленные реплики игроков в один ход и отправить {{char}}';
  }
  const box = el.querySelector('.tg-ng-pending'); if (!box) return;   // панели «Ход в сборке» больше нет — выбор идёт в самой ленте чата (✕ у строк)
  if (!turn.length) { box.innerHTML = ''; box.classList.add('empty'); return; }
  box.classList.remove('empty');
  box.innerHTML = '<div class="tg-ng-pend-h">Ход в сборке — удали лишнее до «Собрать ход»:</div>'
    + turn.map((t, i) => '<div class="tg-ng-pend-row" data-i="' + i + '"><span class="tg-ng-pend-txt"><b>' + escapeConsole(t.persona) + ':</b> ' + escapeConsole(t.text) + '</span><button class="tg-ng-pend-x" type="button" title="Убрать эту реплику из хода">✕</button></div>').join('');
}
// Собрать накопленный ход в ОДНО {{user}} («Персона: действие» построчно) и отправить {{char}}.
async function tgNgSendTurn(el, token, chatId, threadId) {
  const turn = el._ngTurn || [];
  if (!turn.length) { el._setStatus('ход пуст — игроки ещё не писали', 'err'); return; }
  const cid = chatId || el._lastChatId;
  if (!cid) { el._setStatus('нет чата — сначала кто-то должен написать боту', 'err'); return; }
  // Перевод RU→EN — ТОЛЬКО здесь (на «Собрать ход»), построчно, чтобы имена персон НЕ переводились.
  let lines = turn;
  if (tgAutoTr(el)) { lines = []; let trFail = false; for (const t of turn) { const tr = await tgTranslateRetry(t.text, 'en', 'replace'); if (tr == null) trFail = true; lines.push({ ...t, text: (tr != null ? tr : t.text) }); } if (trFail) el._setStatus('⚠ часть реплик хода не перевелась — ушёл оригинал', 'err'); }
  // Ход уходит ОДНИМ сообщением, а игроков в нём может быть трое. Заявки одного игрока склеиваем в ОДНУ
  // реплику: у игрока всегда одна заявка за ход — сколько бы действий он в неё ни написал.
  const byPersona = [];
  lines.forEach((t) => {
    const key = String(t.persona || '');
    const found = byPersona.find((x) => x.persona === key);
    if (found) found.text += String.fromCharCode(10) + t.text; else byPersona.push({ persona: key, text: t.text });
  });
  const compiled = byPersona.map((t) => t.persona + ': ' + t.text).join(String.fromCharCode(10));
  // Броски: по одному на игрока ЭТОГО хода (успех/провал на всю заявку). Уходят скопом с одним лид-промтом.
  const rndEl = (typeof randomNodeForChat === 'function') ? randomNodeForChat(el) : null;
  if (rndEl && typeof randomTakeForTurn === 'function') {
    const rolls = randomTakeForTurn(rndEl, byPersona.map((x) => x.persona));
    // Ведущему видно, что выпало и кому: строка в ленте перед ответом. Броски уходят в промт этого же
    // хода, поэтому строка = «что реально подано модели», а не отдельная выдумка.
    if (rolls && rolls.length && typeof tgFeed === 'function') {
      const human = rolls.map((r) => (r.gm ? 'ведущий (NPC)' : r.persona) + ' — ' + (r.roll === 'success' ? 'успех' : 'провал')).join(' · ');
      tgFeed(el, human, 'in', '⚄ броски', { muted: true });
    }
  }
  const sentIds = new Set(turn.map((t) => t.msgId));   // что реально ушло в ход (выбранное)
  el._ngTurn = [];
  tgNgRenderPending(el);
  const fd = el.querySelector('.tg-feed');   // авто-чистка ленты: ушедшее в ход — оставить записью, невыбранное — убрать
  if (fd) fd.querySelectorAll('.tg-line.tg-cand').forEach((r) => {
    const mid = r.dataset.msgId != null ? Number(r.dataset.msgId) : null;
    if (mid != null && sentIds.has(mid)) { r.classList.remove('tg-cand', 'tg-sel'); const sb = r.querySelector('.tg-sel-box'); if (sb) sb.remove(); }
    else r.remove();
  });
  await telegramReply(el, token, cid, compiled, threadId);
  // Пачка-обновление Душ мультиперсоны: раз в N ходов (настройка ноды). Фоном, ход не блокируем.
  el._ngTurnCount = (el._ngTurnCount || 0) + 1;
  const nb = Math.max(1, parseInt((el.querySelector('.tg-ng-batch') || {}).value, 10) || 1);
  if (el._ngTurnCount % nb === 0) tgNgUpdateSouls(el).catch(() => {});
}
// Старт игры: у игроков ещё нет ни одной записи — сформировать ПЕРВУЮ версию их трекеров (Inventory, Standing
// и любых других включённых) ИЗ ОПИСАНИЯ ПЕРСОНЫ: истории нет, опора только на неё. Уже написанные документы
// не трогаем — сеем только пустые. Дальше их ведёт обычный движок памяти (пачка после хода).
async function tgNgSeedPlayerDocs(el) {
  const say = (t, k) => { if (el._setStatus) el._setStatus(t, k || 'err'); };
  const mu = (typeof tgNgMuser === 'function') ? tgNgMuser(el) : null; if (!mu) { say('нет слота мультипользователя — документы игроков не заполнить'); return; }
  const base = partyChatId(el); if (!base) { say('нет истории партии — документы игроков не заполнить'); return; }
  const api = chatApi(el); if (!api) { say('нет API с ключом у ноды — документы игроков не заполнить'); return; }
  for (const row of [...mu.querySelectorAll('.pm-mu-row')]) {
    if (typeof tgNgRowMuted === 'function' && tgNgRowMuted(el, row)) continue;   // заглушённый — не игрок
    const nmRow = (typeof muRowPersonaName === 'function') ? muRowPersonaName(row) : '';
    const soul = muRowSoulNode(row); if (!soul) { say('к ряду «' + (nmRow || row.dataset.player) + '» не подключена нода «Душа»'); continue; }
    const sheet = (typeof soulPersonaBaseline === 'function') ? soulPersonaBaseline(soul) : '';
    if (!sheet) { say('у «' + (nmRow || row.dataset.player) + '» пустое описание Персоны — из чего писать документы?'); continue; }
    const chat = memPath(base, row.dataset.player);              // личная папка памяти этого игрока
    const charName = (typeof muRowPersonaName === 'function') ? muRowPersonaName(row) : '';
    const mctx = { ...chatNames(el), char: charName };
    const maxtok = Math.max(50, parseInt((soul.querySelector('.soul-maxtok') || {}).value, 10) || 400);
    const tRaw = parseFloat((soul.querySelector('.soul-temp') || {}).value); const temp = isFinite(tRaw) ? tRaw : 0.3;
    if (el._setStatus) el._setStatus('готовлю документы · ' + (charName || 'игрок') + '…', 'ok');
    let wrote = await updateMemoryBatch(el, soul, charName, { seed: true });   // ВСЕ трекеры игрока — одним запросом
    if (!wrote) {   // пачка не отработала — пишем документы по одному, чтобы окно не осталось пустым
      for (const d of (soul._docs || []).filter((x) => x.enabled && x.kind === 'tracker' && String(x.prompt || '').trim())) {
        const instr = substituteMacros(String(d.prompt || ''), mctx).trim();
        const user = sheet + 'Write "' + d.name + '" for ' + (charName || 'this character')
          + ' from the sheet above, following the instruction. Output only the document.';
        const rr = await rlmApi('/api/rlm/generate', { _ctxKey: '.soul-maxtok@.node-soul', _ctxNode: soul, base: api.base, key: api.key, model: api.model,
          messages: [{ role: 'system', content: instr }, { role: 'user', content: substituteMacros(user, mctx) }],
          params: { max_tokens: maxtok + tokVal('soul.think', MEM_THINK_BUDGET_DEF), temperature: temp } });
        const text = memCleanReply(rr);
        if (text) { await rlmApi('/api/rlm/soul/tracker', { chat, name: d.name, text }); wrote = true; }
        else say('«' + d.name + '» · ' + (charName || 'игрок') + ': модель вернула пусто');
      }
    }
    if (wrote && typeof soulFillDocRecords === 'function') { try { await soulFillDocRecords(soul); } catch (_) { /* показ записей не критичен */ } }
  }
}
// «▶ Играть» — старт игры: отправить первое сообщение карточки-движка ({{char}}) в чат, ЗАПЕРЕТЬ тему
// (нода запоминает номер темы — читает/отвечает только в ней) и НАЧАТЬ историю беседы.
async function tgNgStartGame(el, token, chatId, threadId) {
  const cid = chatId || el._lastChatId;
  if (!cid) { el._setStatus('нет чата — сначала кто-то должен написать боту', 'err'); return; }
  const charEl = tgNgCharNode(el);
  const port = charEl && charEl.querySelector('.ch-item[data-field="first_mes"] .port.out');
  let text = port ? sourceText(port, []) : '';
  if (!text || !text.trim()) { el._setStatus('нет первого сообщения у карточки-движка', 'err'); return; }
  // Запереть тему форума, где стартуем (нода помнит номер — дальше читает/отвечает только в ней).
  const startThread = (el._topicFilter != null) ? el._topicFilter : ((threadId != null) ? threadId : el._lastThreadId);
  if (startThread != null && el._topicFilter == null) { el._topicFilter = startThread; if (typeof tgRenderTopics === 'function') tgRenderTopics(el); }   // замок уже стоит — не срываем его командой из другой темы
  const mctx = chatNames(el);
  text = substituteMacros(text, mctx);
  // Начать историю беседы: первое сообщение = приветствие {{char}} (стартовая сцена).
  el._convos = el._convos || {};
  const convo = el._convos[cid] || (el._convos[cid] = { chatId: (typeof chatIdBase === 'function' && el._chatId ? chatIdBase(el._chatId) : genChatId()), msgs: [] });
  tgAddMsg(el, convo, { role: 'char', text, greeting: true });   // старт партии: приветствие ложится на диск сразу
  el._chatId = convo.chatId; el._msgs = convo.msgs; el._lastChatId = cid;
  // Пустые документы игроков (Inventory/Standing) — засеять из их «Персоны», пока сцены ещё нет.
  // Галочка «не обновлять Души на старте» (тесты): документы уже заполнены — не тратим запросы заново.
  if (!(el.querySelector('.tg-noseed') || {}).checked) {
    try { await tgNgSeedPlayerDocs(el); } catch (_) { /* сев не критичен — игра начинается в любом случае */ }
  } else if (el._setStatus) el._setStatus('Души на старте не обновлялись (галочка)', '');
  let outText = text;
  if (tgAutoTr(el)) { const tr = await trTranslate(text, 'ru', 'preview'); if (tr != null) outText = tr; }
  const cn = chatNames(el).char;
  if (el._localMode) { tgFeed(el, '## 🎮 Игра началась\n\n' + outText, 'out', cn, { kb: tgNgKeyboard(el) }); el._setStatus('игра началась (локально)', 'ok'); return; }   // локально: стартовая сцена — в ленту той же разметкой, что ушла бы в Telegram
  if (tgAudMode(el) === 'voice' || tgAudMode(el) === 'mix') {   // «только голосом»/«комбинировать» → стартовую сцену озвучиваем
    const sv = await telegramSendVoice(el, token, cid, outText, (startThread != null ? startThread : null));
    if (sv) { tgFeed(el, '🔊 ' + outText, 'out', cn); el._setStatus('игра началась · слушаю…', 'ok'); return; }
  }
  const startMd = '## 🎮 Игра началась\n\n' + outText;   // rich-плашка: заголовок + первая сцена (лестница сама сведёт к жирному, если rich не прошёл)
  const startKb = tgNgKeyboard(el);
  const sent = await tgSendPretty(el, token, cid, startMd, (startThread != null ? startThread : null), startKb ? { reply_markup: startKb } : undefined);
  if (sent && sent.ok) { convo.lastSent = { messageId: (sent.result || {}).message_id, thread: (startThread != null ? startThread : null), voice: false, rich: !!sent.rich, kb: !!startKb }; tgFeed(el, outText, 'out', cn, { kb: startKb }); el._setStatus('игра началась · слушаю…', 'ok'); }
  else el._setStatus('✗ отправка: ' + ((sent && sent.description) || 'ошибка'), 'err');
}
// Обновить Души ВСЕХ персон слота за один проход. Каждая пишет в СВОЮ папку памяти (baseChat:playerId) —
// личные каналы не смешиваются. Движок памяти (updateMemory) переиспользуем как есть, доки по одному.
// Душа МИРА сетевой игры: та, что подключена к плашке «Память» комплитера (не к ряду игрока).
function tgNgWorldSoul(el) {
  const comp = (typeof tgNgCompleter === 'function') ? tgNgCompleter(el) : null; if (!comp) return null;
  const plate = comp.querySelector('.pm-item[data-id="memory"]'); if (!plate) return null;
  const port = plate.querySelector('.port.in'); if (!port) return null;
  const c = connections.find((x) => x.to === port && x.from.closest && x.from.closest('.node-soul'));
  return c ? c.from.closest('.node-soul') : null;
}
async function tgNgUpdateSouls(el) {
  if (el._ngSoulBusy) return;
  const mu = tgNgMuser(el); if (!mu) return;
  const baseChat = partyChatId(el); if (!baseChat) return;
  const savedChatId = el._chatId;
  el._ngSoulBusy = true;
  if (el._setStatus) el._setStatus('🕯 обновляю Души…', '');
  let touched = 0;
  try {
    // 1) Душа МИРА — ПЕРВОЙ: сцена/следы/часики пишутся до личных листов, чтобы игроки писали НЕ ТО ЖЕ САМОЕ.
    let scene = '';
    const world = tgNgWorldSoul(el);
    if (world) {
      if (el._setStatus) el._setStatus('🕯 Душа мира…', '');
      touched++;
      el._chatId = baseChat;
      const wsheet = ngWorldSheet(el);                     // сеттинг из карточки — чтобы `World` не пересказывал её
      const wb = await updateMemoryBatch(el, world, '', { sheet: wsheet });
      const wdocs = (world._docs || []).filter((d) => d.enabled && d.kind !== 'manual' && !(wb && d.kind === 'tracker'));
      for (const d of wdocs) { await updateMemory(el, { soul: world, docId: d.id, sheet: wsheet }); }
      // свежая «сцена сейчас» → пойдёт игрокам как КОНТЕКСТ (не для переписывания)
      const sc = (world._docs || []).find((d) => d.enabled && /^status$/i.test(String(d.name || '').trim()));
      if (sc) { try { const r = await rlmApi('/api/rlm/soul/get', { chat: baseChat, name: sc.name }); scene = String((r && r.text) || '').trim(); } catch (_) {} }
    }
    // 2) Души ИГРОКОВ — после мира: каждой даём свежую сцену и её числа из «Состояния».
    for (const row of [...mu.querySelectorAll('.pm-mu-row')]) {
      if (tgNgRowMuted(el, row)) continue;   // заглушённый игрок — Душу не обновляем
      const port = row.querySelector('.port.in[data-field="soul"]');
      const conn = port && connections.find((c) => c.to === port && c.from.closest && c.from.closest('.node-soul'));
      const soul = conn ? conn.from.closest('.node-soul') : null;
      if (!soul) continue;
      const charName = muRowPersonaName(row);             // {{char}} доков этой Души = имя персоны
      if (el._setStatus) el._setStatus('🕯 Душа · ' + (charName || 'игрок') + '…', '');
      touched++;
      const nums = tgNgStateLines(el, row);                // что уже ведётся числами — словами не дублировать
      el._chatId = baseChat;                              // пачка сама вычислит папку игрока (иначе вышло бы «чат:игрок:игрок»)
      const batched = await updateMemoryBatch(el, soul, charName, { scene, state: nums });   // все трекеры ЭТОЙ Души — одним запросом
      el._chatId = memPath(baseChat, row.dataset.player);   // память ЭТОЙ персоны — своя папка (для остальных доков)
      const docs = (soul._docs || []).filter((d) => d.enabled && d.kind !== 'manual' && !(batched && d.kind === 'tracker'));
      for (const d of docs) { await updateMemory(el, { soul, docId: d.id, charName, scene, state: nums }); }
    }
  } finally {
    el._chatId = savedChatId; el._ngSoulBusy = false;
    if (el._setStatus) el._setStatus(touched ? ('🕯 Души обновлены · ' + touched) : 'слушаю…', touched ? 'ok' : '');
  }
}

// ── Состояния мультиперсоны: {{char}} одним ответом шлёт изменения ПО ПЕРСОНАМ (тег), мы раскидываем ──
// Нода «Состояние», подключённая к ряду игрока.
function tgNgStateNode(row) {
  const port = row && row.querySelector('.port.in[data-field="state"]');
  const conn = port && connections.find((c) => c.to === port && c.from.closest && c.from.closest('.node-state'));
  return conn ? conn.from.closest('.node-state') : null;
}
// Значения «Состояния» ОДНОГО игрока строками — уходят движку памяти как «это ведётся числами, словами не писать».
function tgNgStateLines(el, row) {
  const sn = tgNgStateNode(row); if (!sn) return '';
  const defs = stateVarDefs(sn); if (!defs.length) return '';
  const name = muRowPersonaName(row); if (!name) return '';
  const cur = tgNgStateValues(el, name, defs);
  return defs.map((v) => {
    const val = stateShowVal(v, cur[v.id]);
    const range = (v.type === 'int' && isFinite(v.max)) ? '/' + v.max : '';
    return '- ' + v.name + ': ' + val + range;
  }).join(String.fromCharCode(10));
}
// Текущие значения персоны (из el._ngStates) поверх дефолтов её Состояния.
function tgNgStateValues(el, name, defs) {
  const store = (el._ngStates && el._ngStates[name]) || {};
  return { ...stateDefaults(defs), ...store };
}
// Блок «состояния всех игроков» в промт: текущие значения по персонам + ОДИН тег-директива на изменения.
function tgNgStateBlock(el) {
  const mu = tgNgMuser(el); if (!mu) return '';
  const perP = []; let firstState = null;
  [...mu.querySelectorAll('.pm-mu-row')].forEach((row) => {
    if (tgNgRowMuted(el, row)) return;   // заглушённый игрок — его состояния вне контекста
    const sn = tgNgStateNode(row); if (!sn) return;
    const defs = stateVarDefs(sn); if (!defs.length) return;
    if (!firstState) firstState = sn;   // ИНСТРУКЦИЯ состояний берётся ОДИН раз — у ПЕРВОЙ ноды «Состояние» (не троится/двоится)
    const name = muRowPersonaName(row); if (!name) return;
    const cur = tgNgStateValues(el, name, defs);
    const lines = defs.map((v) => { const val = stateShowVal(v, cur[v.id]); const range = (v.type === 'int' && isFinite(v.max)) ? '/' + v.max : ''; return `  - ${v.name}: ${val}${range}`; }).join('\n');
    perP.push(`${name}:\n${lines}`);
  });
  if (!perP.length || !firstState) return '';
  const promptHead = (String((firstState.querySelector('.st-prompt') || {}).value || '').trim()) || STATE_PROMPT_DEFAULT;   // «Инструкция ИИ» первой ноды состояний — одна на всех
  // Счетовод включён → ведущий про цифры НЕ думает: значения он видит (играть по ним), но тег считает отдельный проход.
  if (tgNgTallyOn(el)) return `[STATES OF ALL PLAYERS]\n${promptHead}\n\nCurrent values per character:\n${perP.join('\n')}\n\nPlay by these values — show what they mean in the scene. Do NOT output any tag and do not state numbers: the bookkeeping is done elsewhere.`;
  return `[STATES OF ALL PLAYERS]\n${promptHead}\n\nCurrent values per character:\n${perP.join('\n')}\n\nThe values above are ALREADY UP TO DATE: everything that happened in earlier turns is counted in them. Report ONLY what the NEWEST turn changed — never charge a wound, a cost or a gain a second time because it is still visible in the scene or in the log. A character who is already hurt does not lose health again for being hurt; they lose it only from something NEW that happens to them. If nothing changed for someone, leave them out. When someone pays, buys, gives away or is robbed, subtract it — if no exact price was named, use a plain, sensible one for such a thing in this world. \n\nAt the VERY END of your reply, after the scene, add ONE tag with what changed this turn, PER CHARACTER (deltas: numbers +N/-N, lists +item/-item, flags true/false); include only what changed.\nFormat: <state_update>{"CharacterName": {"Var": "-5"}}</state_update>\nWrite nothing after the tag.`;
}
// РАСКИДАТЬ готовые изменения по Состояниям персон (по имени костюма). Общее для тега ведущего и Счетовода.
function tgNgApplyUpdates(el, updates) {
  if (!updates || typeof updates !== 'object') return 0;
  el._ngStates = el._ngStates || {};
  const mu = tgNgMuser(el);
  const rows = mu ? [...mu.querySelectorAll('.pm-mu-row')] : [];
  let hits = 0;
  Object.entries(updates).forEach(([persona, changes]) => {
    const key = String(persona).trim().toLowerCase();
    const row = rows.find((r) => muRowPersonaName(r).toLowerCase() === key);
    if (!row || !changes || typeof changes !== 'object') return;
    const sn = tgNgStateNode(row); if (!sn) return;
    const defs = stateVarDefs(sn); if (!defs.length) return;
    const name = muRowPersonaName(row);
    el._ngStates[name] = stateApply(defs, tgNgStateValues(el, name, defs), changes).values;
    hits++;
  });
  if (hits && typeof persistCurrentGraph === 'function') persistCurrentGraph();   // значения игроков — часть партии, без этого «пропадали» при следующем открытии
  return hits;
}
// Разобрать тег из ответа {{char}} и раскидать изменения. Возвращает чистый текст (без тега).
function tgNgApplyStates(el, text) {
  const parsed = stateParseUpdate(text);
  tgNgApplyUpdates(el, parsed.updates);
  return parsed.clean;
}
// ── СЧЕТОВОД: отдельный проход ТОЛЬКО по числам ────────────────────────────────────
// Ведущий пишет сцену и о значениях не думает вовсе — иначе он списывает одну и ту же рану каждый ход
// (проверено: рана −35 начислялась трижды подряд). Здесь у модели одна задача: сравнить прошлый ход с новым
// и выдать JSON изменений. Ни прозы, ни сюжета.
// Счетовод включён? Настройка живёт в ноде «Критик» этого чата (в телеграм-опциях — только зеркало).
// Нет ноды Критика — считать некому: возвращаемся к прежнему поведению (тег пишет сам ведущий).
function tallyOnFor(chatNode) {
  const cr = (typeof criticNodeForChat === 'function') ? criticNodeForChat(chatNode) : null;
  const c = cr && cr.querySelector('.crit-tally');
  return !!(c && c.checked);
}
function tgNgTallyOn(el) { return tallyOnFor(el); }
// Задание счетоводу: значения + прошлый ход (уже посчитан) + действия игроков + новая сцена → JSON изменений.
function tallyUserPrompt(blocks, prevScene, lastAct, sceneText) {
  return 'CURRENT VALUES (already include everything that happened before this turn):' + BSN + blocks
    + (prevScene ? BSN + BSN + 'PREVIOUS TURN (already accounted for — never charge anything from it again):' + BSN + String(prevScene).slice(0, 2000) : '')
    + (lastAct ? BSN + BSN + 'WHAT THE PLAYERS JUST DID:' + BSN + String(lastAct).slice(0, 1500) : '')
    + BSN + BSN + 'THE NEW TURN (this is what you are counting):' + BSN + String(sceneText || '').slice(0, 4000)
    + BSN + BSN + 'Work out what the NEW TURN alone changed for each character:' + BSN
    + '- A wound already suffered earlier does not cost health again for still hurting; only a NEW injury does.' + BSN
    + '- Someone who paid, bought, gave away or was robbed loses that amount; if no price was named, use a plain sensible one.' + BSN
    + '- Gains count too: found, earned, taken, healed, treated, rested.' + BSN
    + '- Nothing happened to a value? Leave it out. Nobody changed? Answer {}.' + BSN
    + '- Stay inside each range; a value cannot go past its limits.' + BSN + BSN
    + 'Answer with ONE JSON object and nothing else — deltas for numbers (+N / -N), +item / -item for lists, true / false for flags:' + BSN
    + '{"CharacterName": {"Var": "-5"}}';
}
// Спросить модель и вынуть JSON (температура 0 — это арифметика, не сочинение).
async function tallyAsk(api, user, stNode) {
  try {
    const r = await rlmApi('/api/rlm/generate', { _ctxKey: 'state.tally', _ctxNode: stNode, base: api.base, key: api.key, model: api.model,
      messages: [{ role: 'system', content: NG_TALLY_SYS }, { role: 'user', content: user }],
      params: { max_tokens: tokVal('state.tally', 400) + tokVal('soul.think', MEM_THINK_BUDGET_DEF), temperature: 0 } });
    const raw = (typeof memCleanReply === 'function') ? memCleanReply(r) : String((r && r.content) || '');
    const m = String(raw).match(/\{[\s\S]*\}/);
    if (!m) return null;
    try { return JSON.parse(m[0]); } catch (_) { return null; }
  } catch (e) { return null; }
}
// Строка переменной для счетовода: значение + границы + пояснение ведущего.
function tallyVarLines(defs, cur) {
  return defs.map((v) => {
    const val = stateShowVal(v, cur[v.id]);
    const rng = (v.type === 'int') ? ('  [' + v.min + '..' + v.max + ']') : (v.type === 'list' ? '  [list]' : '  [true/false]');
    return '  - ' + v.name + ': ' + val + rng + (v.desc ? '  \u2014 ' + v.desc : '');
  }).join(BSN);
}
// ОБЫЧНЫЙ ЧАТ (сингл/группа): посчитать значения отдельным проходом. Возвращает {values, reasons} или null.
async function tallyChatStates(chatNode, sceneText) {
  const st = stateNodeForChat(chatNode); if (!st) return null;
  const defs = stateVarDefs(st); if (!defs.length) return null;
  const api = (typeof chatApi === 'function') ? chatApi(chatNode) : null; if (!api) return null;
  const msgs = chatNode._msgs || [];
  const prev = stateCurrentValues(defs, msgs);
  const names = (typeof chatNames === 'function') ? chatNames(chatNode) : { char: 'the character' };
  const blocks = (names.char || 'the character') + ':' + BSN + tallyVarLines(defs, prev);
  const prevScene = [...msgs].reverse().find((m) => m.role === 'char');
  const lastAct = [...msgs].reverse().find((m) => m.role === 'user');
  const obj = await tallyAsk(api, tallyUserPrompt(blocks, prevScene && prevScene.text, lastAct && lastAct.text, sceneText), st);
  if (!obj) return null;
  // счетовод может ответить и «по персонажу», и плоско {"HP": "-5"} — принимаем оба вида
  const key = Object.keys(obj).find((k) => String(k).trim().toLowerCase() === String(names.char || '').trim().toLowerCase());
  const changes = key ? obj[key] : obj;
  const applied = stateApply(defs, prev, changes);
  return { values: applied.values, reasons: (Object.keys(applied.reasons || {}).length ? applied.reasons : null) };
}
const NG_TALLY_SYS = 'You are the bookkeeper of a roleplay game. You never write story, never judge quality, never speak to anyone. '
  + 'You are given each character\'s tracked values and the latest turn of play. You decide ONLY what those values became, and answer with JSON and nothing else.';
async function tgNgTally(el, sceneText) {
  const mu = tgNgMuser(el); if (!mu) return null;
  const api = (typeof chatApi === 'function') ? chatApi(el) : null; if (!api) return null;
  const rows = [...mu.querySelectorAll('.pm-mu-row')].filter((r) => !tgNgRowMuted(el, r));
  const blocks = [];
  rows.forEach((row) => {
    const sn = tgNgStateNode(row); if (!sn) return;
    const defs = stateVarDefs(sn); if (!defs.length) return;
    const name = muRowPersonaName(row); if (!name) return;
    const cur = tgNgStateValues(el, name, defs);
    const lines = defs.map((v) => {
      const val = stateShowVal(v, cur[v.id]);
      const rng = (v.type === 'int') ? ('  [' + v.min + '..' + v.max + ']') : (v.type === 'list' ? '  [list]' : '  [true/false]');
      return '  - ' + v.name + ': ' + val + rng + (v.desc ? '  — ' + v.desc : '');
    }).join('\n');
    blocks.push(name + ':\n' + lines);
  });
  if (!blocks.length) return null;
  const msgs = (el._msgs || []);
  const prevScene = [...msgs].reverse().find((m) => m.role === 'char');
  const lastAct = [...msgs].reverse().find((m) => m.role === 'user');
  const obj = await tallyAsk(api, tallyUserPrompt(blocks.join(BSN), prevScene && prevScene.text, lastAct && lastAct.text, sceneText));
  if (!obj) return null;
  return { updates: obj, hits: tgNgApplyUpdates(el, obj) };
}
// Сводка состояний под ответом (в Telegram/лог): по персоне — её значения.
// ── Подпрограмма ОФОРМЛЕНИЯ состояний для Telegram (рисует КОД, не модель) ──────────
// Число с максимумом (HP и т.п.) → символьная полоска ▰▱ по проценту; модель только сообщает значение тегом.
function tgStateBar(n, min, max, total) {
  total = total || 10;
  const pct = Math.max(0, Math.min(1, (n - min) / (max - min)));
  const filled = Math.round(pct * total);
  return '▰'.repeat(filled) + '▱'.repeat(Math.max(0, total - filled));
}
// Оформить ОДНУ переменную состояния: int с min/max → «Имя ▰▰▰▱▱ 7/10», иначе — «Имя значение».
function tgFormatStateVar(v, raw) {
  const n = parseFloat(raw);
  if (v.type === 'int' && isFinite(v.min) && isFinite(v.max) && v.max > v.min && isFinite(n)) {
    return v.name + ' ' + tgStateBar(n, v.min, v.max) + ' ' + stateShowVal(v, raw) + '/' + v.max;
  }
  return v.name + ' ' + stateShowVal(v, raw);
}
// ── Пакер разметки: оформляет ответ КОД, а не модель ───────────────────────────────
// Модель пишет обычную прозу (у неё и так хватает работы) — разметку навешиваем здесь, уже ПОСЛЕ
// перевода, чтобы переводчик её не съел: имена — жирным (по разу на сообщение), «Имя:» в начале
// строки — жирным, реплики с тире — цитатой. Звёздочки модели не трогаем.
function tgNgNames(el) {
  const out = [];
  const cn = ((typeof chatNames === 'function' ? chatNames(el) : {}) || {}).char;
  if (cn) out.push(cn);
  const mu = (typeof tgNgMuser === 'function') ? tgNgMuser(el) : null;
  if (mu) [...mu.querySelectorAll('.pm-mu-row')].forEach((row) => { const n = muRowPersonaName(row); if (n) out.push(n); });
  return [...new Set(out)].filter((n) => n && n.length > 1);
}
// Починка таблиц: и модель, и переводчик регулярно ломают их (теряется строка-разделитель,
// разное число ячеек в строках). Telegram такую таблицу рисовать не станет — покажет сырой текст.
// Поэтому программа приводит её в порядок сама, ни на кого не полагаясь.
function tgFixTables(md) {
  const lines = String(md == null ? '' : md).split('\n');
  const isRow = (l) => /^\s*\|.*\|\s*$/.test(l) && !/^\s*\|\|/.test(l);
  const isSep = (l) => /^\s*\|[\s:|-]+\|\s*$/.test(l);
  const cells = (l) => l.trim().replace(/^\||\|$/g, '').split('|').map((c) => c.trim());
  const out = [];
  let i = 0;
  while (i < lines.length) {
    if (!isRow(lines[i])) { out.push(lines[i++]); continue; }
    const block = [];
    while (i < lines.length && isRow(lines[i])) block.push(lines[i++]);
    const rows = block.filter((l) => !isSep(l)).map(cells);
    if (rows.length < 2) { out.push(...block); continue; }        // одна строка — не таблица, не трогаем
    const n = Math.max(...rows.map((r) => r.length));
    const norm = rows.map((r) => { const c = r.slice(0, n); while (c.length < n) c.push(''); return '| ' + c.join(' | ') + ' |'; });
    if (out.length && String(out[out.length - 1]).trim()) out.push('');   // пустая строка ПЕРЕД таблицей — иначе она склеится с текстом
    out.push(norm[0], '|' + Array(n).fill(':--').join('|') + '|', ...norm.slice(1));   // шапка + разделитель + тело
    if (i < lines.length && String(lines[i]).trim()) out.push('');   // и ПОСЛЕ таблицы
  }
  return out.join('\n');
}
function tgNgAutoMarkup(el, text) {
  let t = String(text == null ? '' : text);
  if (!t.trim()) return t;
  // ПОЧИНКА РАЗМЕТКИ: маркеры работают только В НАЧАЛЕ СТРОКИ. Если текст вставили одной строкой
  // (или переносы съело поле), «>» и «---» оказывались посреди абзаца и уходили как символы.
  // Возвращаем им начало строки, а заголовкам — пустую строку перед собой.
  const NLC = String.fromCharCode(10);
  t = t.replace(/\s*(?:^|(?<=\S))\s+(?=>\s)/g, NLC)          // «… текст > цитата» → перенос перед >
       .replace(/(?<=\S)[ 	]+(?=---\s)/g, NLC + NLC)          // разделитель — с новой строки
       .replace(/(?<=\S)[ 	]+(?=#{1,3}\s)/g, NLC + NLC);      // заголовок — с новой строки

  const rx = (x) => x.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  // Перевод часто разносит звёздочки модели: «* она вздрогнула *» — такая пара уже не работает.
  // Сначала чиним ЕЁ разметку, потом ставим свою.
  t = t.replace(/\*\*\s+([^*\n]+?)\s+\*\*/g, '**$1**')
       .replace(/(^|[^*])\*\s+([^*\n]+?)\s+\*(?!\*)/g, '$1*$2*');
  // Имена: у персоны имя бывает длинным («Леон маленькая девочка»), а в тексте — только «Леон».
  // Поэтому ищем и полное имя, и его отдельные слова (кроме коротких и служебных).
  const STOP = /^(маленьк|девочк|мальчик|the|of|и|a)/i;
  const names = [];
  tgNgNames(el).forEach((full) => {
    names.push(full);
    full.split(/\s+/).forEach((w) => { if (w.length > 2 && !STOP.test(w) && !names.includes(w)) names.push(w); });
  });
  names.sort((a, b) => b.length - a.length);   // сперва длинные — иначе «Леон» съест «Леон маленькая девочка»
  names.forEach((n) => { t = t.replace(new RegExp('^[ \\t]*(' + rx(n) + ')[ \\t]*:', 'gm'), '**$1:**'); });
  names.forEach((n) => {
    const re = new RegExp('(^|[^\\p{L}\\p{N}_*])(' + rx(n) + ')(?![\\p{L}\\p{N}_*:])', 'u');
    if (re.test(t)) t = t.replace(re, (m, pre, nm) => pre + '**' + nm + '**');
  });
  // Прямая речь — в цитату. Модель пишет её и с тире, и в кавычках («…», "…", “…”).
  t = t.replace(/^[ \t]*([—–])[ \t]+(?=\S)/gm, '> $1 ');
  t = t.replace(/^[ \t]*(["«“][^\n]*)$/gm, '> $1');
  return tgFixTables(t);   // таблицы — в правильный вид, что бы туда ни попало от модели или переводчика
}
// Сводка состояний под ответом. Rich-разметка умеет таблицы — когда у всех персон один набор
// переменных, рисуем ТАБЛИЦУ (персонажи строками, показатели столбцами): читается куда лучше списка.
// Наборы разные (у кого-то свои поля) — падаем на прежний построчный вид.
function tgStateVarValue(v, raw) {
  if (raw == null || raw === '') return '—';   // значения ещё нет — прочерк, а не «undefined»
  const n = parseFloat(raw);
  if (v.type === 'int' && isFinite(v.min) && isFinite(v.max) && v.max > v.min && isFinite(n)) {
    return tgStateBar(n, v.min, v.max) + ' ' + stateShowVal(v, raw) + '/' + v.max;
  }
  return stateShowVal(v, raw);
}
function tgNgStateHud(el) {
  const mu = tgNgMuser(el); if (!mu) return '';
  const rows = [];
  [...mu.querySelectorAll('.pm-mu-row')].forEach((row) => {
    if (tgNgRowMuted(el, row)) return;   // заглушённый игрок — не в сводке
    const sn = tgNgStateNode(row); if (!sn) return;
    const defs = stateVarDefs(sn); if (!defs.length) return;
    const name = muRowPersonaName(row); if (!name) return;
    rows.push({ name, defs, cur: tgNgStateValues(el, name, defs) });
  });
  if (!rows.length) return '';
  const head = rows[0].defs.map((v) => v.name).join('|');
  const same = rows.every((r) => r.defs.map((v) => v.name).join('|') === head);
  if (same) {                                   // таблица: строки — персонажи, столбцы — показатели
    const cols = rows[0].defs;
    const out = ['| Персонаж | ' + cols.map((v) => v.name).join(' | ') + ' |',
                 '|:--|' + cols.map(() => ':--|').join('')];
    rows.forEach((r) => { out.push('| **' + r.name + '** | ' + cols.map((v) => tgStateVarValue(v, r.cur[v.id])).join(' | ') + ' |'); });
    return '\n**Состояния**\n\n' + out.join('\n');   // пустая строка между заголовком и таблицей — обязательна
  }
  const lines = rows.map((r) => '▸ **' + r.name + '** — ' + r.defs.map((v) => tgFormatStateVar(v, r.cur[v.id])).join(' · '));
  return '\n**Состояния**\n' + lines.join('\n');
}

// АДМИН-АТМОСФЕРА
// Ведущий заранее кладёт картинку и/или звук — они уйдут со СЛЕДУЮЩИМ ответом: фото ПЕРЕД текстом
// (отдельным сообщением — у подписи к фото потолок 1024 символа, а сцена бывает длиннее), звук — ПОСЛЕ.
function tgAtmRead(file) {
  return new Promise((res) => {
    const fr = new FileReader();
    fr.onload = () => { const r = String(fr.result || ''); res({ b64: r.slice(r.indexOf(',') + 1), mime: file.type || '', name: file.name || 'file', url: r }); };
    fr.onerror = () => res(null);
    fr.readAsDataURL(file);
  });
}
function tgAtmSync(el) {
  ['img', 'aud', 'doc'].forEach((k) => {   // doc — произвольный файл: слот тоже должен показывать имя
    const slot = el.querySelector('.tg-atm-slot[data-kind="' + k + '"]'); if (!slot) return;
    const v = (el._atm || {})[k];
    slot.hidden = !v;
    if (!v) return;
    const nm = slot.querySelector('.tg-atm-name'); if (nm) nm.textContent = v.name;
    const th = slot.querySelector('.tg-atm-thumb'); if (th) th.src = v.url || '';
  });
}
function tgAtmWire(el) {
  el.querySelectorAll('.tg-atm-pick').forEach((btn) => {
    btn.addEventListener('pointerdown', (e) => e.stopPropagation());
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      const kind = btn.dataset.kind;
      const inp = document.createElement('input');
      inp.type = 'file'; inp.accept = kind === 'img' ? 'image/*' : (kind === 'aud' ? 'audio/*' : '');   // doc — любой файл
      inp.addEventListener('change', async () => {
        const f = inp.files && inp.files[0]; if (!f) return;
        const data = await tgAtmRead(f);
        if (!data) { el._setStatus('✗ не смог прочитать файл', 'err'); return; }
        el._atm = el._atm || {}; el._atm[kind] = data;
        tgAtmSync(el);
        el._setStatus((kind === 'img' ? '🖼 картинка' : (kind === 'aud' ? '🎵 звук' : '📎 файл')) + ' уйдёт со следующим ответом', 'ok');
      });
      inp.click();
    });
  });
  el.querySelectorAll('.tg-atm-slot .tg-atm-x').forEach((x) => {
    x.addEventListener('pointerdown', (e) => e.stopPropagation());
    x.addEventListener('click', (e) => {
      e.stopPropagation();
      const kind = x.closest('.tg-atm-slot').dataset.kind;
      if (el._atm) delete el._atm[kind];
      tgAtmSync(el);
    });
  });
}
// ── ФОН ЛЕНТЫ («Атмосфера» → «Фон ленты») ───────────────────────────────────────
// Картинка (PNG/JPG) или видео (MP4) ложится ПОД колонку чата: лента, события, полоса процесса и
// поле ввода едут поверх неё. Это декорация ВЕДУЩЕГО — в Telegram фон не уходит (Bot API не умеет
// менять вид чата у игроков). Два регулятора: размытие (blur самой картинки) и приглушение —
