let _tgBgData;        // { url, name, kind:'img'|'vid' } | null | undefined (ещё не читали с сервера)
let _tgBgLoading;     // общий промис загрузки — ноды строятся параллельно, тянем ключ один раз
let _tgBgVer = 0;     // версия файла: по ней решаем, пересобирать ли <img>/<video> (data-URL не сравниваем — он огромный)

// Параметры фона из контролов ноды (или дефолты, если панели нет).
function tgBgParams(el) {
  const rd = (sel, def) => { const i = el.querySelector(sel); const v = i ? parseFloat(i.value) : NaN; return isNaN(v) ? def : v; };
  const mRb = el.querySelector('.tg-bg-mode:checked');
  return { blur: rd('.tg-bg-blur', TG_BG_DEF.blur), dim: rd('.tg-bg-dim', TG_BG_DEF.dim), mode: (mRb && mRb.value) || TG_BG_DEF.mode, glow: rd('.tg-bg-glow', TG_BG_DEF.glow), glowR: rd('.tg-bg-glow-r', TG_BG_DEF.glowR), fade: rd('.tg-bg-fade', TG_BG_DEF.fade) };
}
// Нарисовать фон в ОДНОЙ ноде: медиа + плёнка. Зовём и при смене файла, и при движении ползунка.
// Картинка фона должна кончаться там, где кончается лента: ниже идут события, статус, ввод и доки —
// там читают и печатают, картинка под ними мешает. Считаем высоту нижней зоны и обрезаем слой фона.
// Пересчёт ПОСЛЕ раскладки: высота ленты меняется не в момент клика, а когда браузер пересчитает флексы
