  const rx = Math.round(Math.max(bw * 0.72, f.width / sc * 0.9) * k), ry = Math.round(Math.max(bh * 0.55, f.height / sc * 0.9) * k);
  const m = 'radial-gradient(' + rx + 'px ' + ry + 'px at ' + (fx / w * 100).toFixed(1) + '% ' + (fy / h * 100).toFixed(1) + '%, '
