// Нода Telegram — «безэкранный Чат»: конец пайплайна ВМЕСТО ноды Чат. Ответ персонажа уходит не в
// окно на экране, а боту в Telegram (почтальон: getUpdates/sendMessage). Ноду Чат не трогаем —
// ролеплей на экране и бот живут раздельно; хочешь бота — цепляешь эту ноду вместо Чата.
// Вход слева — от ноды API (как у Чата). Держит свою историю (_convos: chat_id → сообщения), поэтому
// общие функции пайплайна работают с ней, как с чат-нодой. (Этап 1: каркас + опции; почтальон и ИИ — далее.)
// «Сетевая игра» (телеграм-мультиплеер) — ОТДЕЛЬНАЯ нода = КОПИЯ `Telegram` (класс node-telegram + node-netgame:
// все телеграм-функции работают), но под сетевую игру (мультиперсона / компиляция ходов / пачка-обновление душ —
// впереди). Отдельная сущность, чтобы сингл-`Telegram` не трогать. Тип узла — 'netgame'. Дефолт-режим — Группа.
function buildNetgameNode() {
  const el = buildTelegramNode();
  el.classList.add('node-netgame');
  tgAtmWire(el);   // админ-панель: выбор картинки/звука «Атмосферы»
  const lbl = el.querySelector('.node-head .label'); if (lbl) lbl.textContent = 'Телеграм сетевая игра';
  const ico = el.querySelector('.node-head .icon'); if (ico) ico.textContent = '⚄';   // глиф-кубик (перекрашивается в сиреневый — CSS)
  const mode = el.querySelector('.tg-mode'); if (mode) mode.value = 'group';           // сетевая игра — всегда группа
  const cast = el.querySelector('.tg-cast'); if (cast) cast.style.display = '';        // панель участников сразу видна
  // Кнопка «Собрать ход» — ручной триггер сборки хода (второй способ, кроме обращения к боту в чате).
  const btnsRow = el.querySelector('.tg-set-row.tg-btns');
  if (btnsRow) {
    const pb = document.createElement('button');   // ▶ Играть — старт: первое сообщение карточки в чат + запереть тему + начать историю
    pb.className = 'btn ghost tg-ng-play'; pb.type = 'button'; tgSetBtn(pb, 'play', 'Играть');
    pb.title = 'Старт игры: отправить первое сообщение карточки-движка в чат, запереть тему, начать историю';
    pb.addEventListener('pointerdown', (e) => e.stopPropagation());
    pb.addEventListener('click', async (e) => {
      e.stopPropagation();
      if (pb.disabled) return;   // защита от повторного клика, пока идёт генерация (иначе N кликов = N параллельных запусков)
      pb.disabled = true;
      try {
        const token = ((el.querySelector('.tg-token') || {}).value || el._token || '').trim();
        await tgNgStartGame(el, token, tgTargetChat(el), tgOutThread(el));   // старт партии — в запертую тему, а не в ту, где болтали последней
      } finally { pb.disabled = false; }
    });
    const topActs = el.querySelector('.tg-top-acts');   // «Играть» — в верхней строке ноды, рядом с «Запустить бота» и «Очистить» (частые действия партии на виду)
    if (topActs) topActs.insertBefore(pb, topActs.firstChild); else btnsRow.insertBefore(pb, btnsRow.firstChild);
    const b = document.createElement('button');
    b.className = 'btn ghost tg-ng-send'; b.type = 'button'; tgSetBtn(b, 'stack', 'Собрать ход');
    b.title = 'Склеить накопленные реплики игроков в один ход и отправить {{char}}';
    b.addEventListener('pointerdown', (e) => e.stopPropagation());
    b.addEventListener('click', async (e) => {
      e.stopPropagation();
      if (b.disabled) return;   // защита от повторного клика, пока идёт генерация (иначе N кликов = N параллельных ходов)
      b.disabled = true;
      try {
        const token = ((el.querySelector('.tg-token') || {}).value || el._token || '').trim();
        const thread = tgOutThread(el);   // замок сильнее «последней темы»
        await tgNgSendTurn(el, token, tgTargetChat(el), thread);
      } finally { b.disabled = false; }
    });
    btnsRow.insertBefore(b, btnsRow.firstChild);   // «Собрать ход» — первой в ряду действий, следом «Написать самому»
    // «Собрать сцену» — как в сингле: появляется, когда в ленте отмечены каретки ►◄ (начало и конец).
    const sb = document.createElement('button');
    sb.className = 'btn ghost tg-ng-scene'; sb.type = 'button'; tgSetBtn(sb, 'scene', 'Собрать сцену');
    sb.title = 'Сжать отмеченный ►◄ кусок в запись Хроники (нужна нода «Хроника» на нижней ножке)';
    sb.style.display = 'none';
    sb.addEventListener('pointerdown', (e) => e.stopPropagation());
    sb.addEventListener('click', async (e) => {
      e.stopPropagation();
      if (sb.disabled) return;
      sb.disabled = true;
      try { await tgSceneBuild(el); } finally { sb.disabled = false; }
    });
    btnsRow.appendChild(sb);
    btnsRow.querySelectorAll('.btn').forEach((x) => x.classList.add('tg-iconly'));   // ряд под лентой — только значки (подпись — в подсказке)
    // Панели «Ход в сборке» НЕТ: реплики-кандидаты видны и удаляются прямо в ленте чата (✕ у каждой строки).
    // «Собрать ход» берёт то, что осталось в ленте (буфер el._ngTurn синхронен ленте по msgId), переводит и шлёт.
  }
  // Настройка «обновлять Души каждые N ходов» (пачка-обновление мультиперсоны) — в админ-панели, раздел «Опции».
  const optsSec = el.querySelector('.tg-admin [data-sec="opts"]');
  if (optsSec) {
    const row = document.createElement('div');
    row.className = 'tg-ng-cfg';
    row.innerHTML = '<div class="tg-adm-t2">Обновлять Души</div>'
      + '<label class="tg-ng-batch-lbl" title="Через сколько собранных ходов пачкой перечитать диалог и обновить Души всех персон">каждые '
      + '<input class="field num tg-ng-batch" type="number" min="1" value="1" spellcheck="false"> ходов</label>'
      + '<label class="tg-opt tg-ng-tally-lbl" title="Значения считает ОТДЕЛЬНЫЙ проход после ответа: ведущий пишет сцену и цифры не трогает. Лечит двойное списание одной и той же раны/траты. +1 запрос к модели на ход">'
      + '<input type="checkbox" class="tg-ng-tally" checked> 🧮 Счетовод (значения — отдельным проходом)</label>';
    row.querySelector('.tg-ng-batch').addEventListener('pointerdown', (e) => e.stopPropagation());
    row.querySelector('.tg-ng-tally').addEventListener('pointerdown', (e) => e.stopPropagation());
    row.querySelector('.tg-ng-tally').addEventListener('change', (e) => {   // зеркало: настоящая галочка — в ноде «Критик»
      const cr = (typeof criticNodeForChat === 'function') ? criticNodeForChat(el) : null;
      const c = cr && cr.querySelector('.crit-tally');
      if (c) { c.checked = e.target.checked; persistCurrentGraph(); }
      else { e.target.checked = false; el._setStatus('⚠ Счетовод живёт в ноде «Критик» — подключи её к ножке «Критик»', 'err'); }
    });
    optsSec.appendChild(row);
  }
  return el;
}
