  const startModelPoll = () => { if (!el._tgModelTimer) el._tgModelTimer = setInterval(() => tgModelHealth(el), 2500); tgModelHealth(el); };
  const stopModelPoll = () => { if (el._tgModelTimer) { clearInterval(el._tgModelTimer); el._tgModelTimer = null; } };
  const setStatus = (text, state) => { el._statusText = text; el._statusState = state || ''; if (typeof tgStatusRender === 'function') tgStatusRender(el); };
  el._setStatus = setStatus;
  setTimeout(() => { if (typeof tgRenderGuests === 'function') tgRenderGuests(el); if (typeof tgRenderEvents === 'function') tgRenderEvents(el); }, 0);   // список гостей — после сборки графа (лорбук чата уже на месте)
  // Токен сохраняем сразу при вводе (как ключ API) — не пропадёт при перезапуске.
