  if (cfg.wait && el.querySelector('.tg-wait-text')) el.querySelector('.tg-wait-text').value = cfg.wait;
  if (el.querySelector('.tg-wait-on')) el.querySelector('.tg-wait-on').checked = (cfg.waitOn !== false);
