  if (cfg.bubInColor != null) _tgBubInColor = cfg.bubInColor;   // то же для плашки ответа игрока
  if (cfg.bubInAlpha != null) _tgBubInAlpha = cfg.bubInAlpha;
  if (cfg.bubAlpha != null) _tgBubAlpha = cfg.bubAlpha;   // её прозрачность
